393	pub(crate) fn handle_group(
394	    fc: &mut FrameContext,
395	    group: &GroupItem,
396	    surface: &mut Surface,
397	    gc: &mut GlobalContext,
398	) -> SourceResult<()> {
399	    fc.push();
400	    fc.state_mut().pre_concat(group.transform);
401	
402	    tags::group(gc, fc, surface, group.parent, |gc, fc, surface| {
403	        let clip_path = group
404	            .clip
405	            .as_ref()
406	            .and_then(|p| {
407	                let mut builder = PathBuilder::new();
408	                convert_path(p, &mut builder);
409	                builder.finish()
410	            })
411	            .and_then(|p| p.transform(fc.state().transform.to_krilla()));
412	
413	        if let Some(clip_path) = &clip_path {
414	            surface.push_clip_path(clip_path, &krilla::paint::FillRule::NonZero);
415	        }
416	
417	        let res =
418	            handle_frame(fc, &group.frame, Sides::splat(Abs::zero()), None, surface, gc);
419	
420	        if clip_path.is_some() {
421	            surface.pop();
422	        }
423	
424	        res
425	    })?;
426	
427	    fc.pop();
428	
429	    Ok(())
430	}
