535	/// Converts a krilla error into a Typst error.
536	fn convert_error(
537	    gc: &GlobalContext,
538	    failing_validators: Validators,
539	    error: &ValidationError,
540	    pdf_version: PdfVersion,
541	) -> SourceDiagnostic {
542	    let prefix = eco_format!("{} error:", failing_validators.to_comma_list());
543	    match error {
544	        ValidationError::TooLongString => error!(
545	            Span::detached(),
546	            "{prefix} a PDF string is longer than 32767 characters";
547	            hint: "ensure title and author names are short enough";
548	        ),
549	        // Should in theory never occur, as krilla always trims font names.
550	        ValidationError::TooLongName => error!(
551	            Span::detached(),
552	            "{prefix} a PDF name is longer than 127 characters";
553	            hint: "perhaps a font name is too long";
554	        ),
555	
556	        ValidationError::TooLongArray => error!(
557	            Span::detached(),
558	            "{prefix} a PDF array is longer than 8191 elements";
559	            hint: "this can happen if you have a very long text in a single line";
560	        ),
561	        ValidationError::TooLongDictionary => error!(
562	            Span::detached(),
563	            "{prefix} a PDF dictionary has more than 4095 entries";
564	            hint: "try reducing the complexity of your document";
565	        ),
566	        ValidationError::TooLargeFloat => error!(
567	            Span::detached(),
568	            "{prefix} a PDF floating point number is larger than the allowed limit";
569	            hint: "try exporting with a higher PDF version";
570	        ),
571	        ValidationError::TooManyIndirectObjects => error!(
572	            Span::detached(),
573	            "{prefix} the PDF has too many indirect objects";
574	            hint: "reduce the size of your document";
575	        ),
576	        // Can only occur if we have 27+ nested clip paths
577	        ValidationError::TooHighQNestingLevel => error!(
578	            Span::detached(),
579	            "{prefix} the PDF has too high q nesting";
580	            hint: "reduce the number of nested containers";
581	        ),
582	        ValidationError::ContainsPostScript(loc) => error!(
583	            to_span(*loc),
584	            "{prefix} the PDF contains PostScript code";
585	            hint: "conic gradients are not supported in this PDF standard";
586	        ),
587	        ValidationError::MissingCMYKProfile => error!(
588	            Span::detached(),
589	            "{prefix} the PDF is missing a CMYK profile";
590	            hint: "CMYK colors are not yet supported in this export mode";
591	        ),
592	        ValidationError::InconsistentSeparationFallback(colorant) => {
593	            let repr = Option::<SpotColorantName>::from_krilla(colorant).repr();
594	            error!(
595	                Span::detached(),
596	                "spot colorant `{repr}` appeared with multiple distinct fallback colors";
597	                hint: "define a particular spot colorant once and store it in a variable to reuse it later";
598	            )
599	        }
600	        ValidationError::ContainsNotDefGlyph(f, loc, text) => error!(
601	            to_span(*loc),
602	            "{prefix} the text `{}` could not be displayed with {}",
603	            text.repr(),
604	            display_font(gc.fonts_backward.get(f));
605	            hint: "try using a different font";
606	        ),
607	        ValidationError::NoCodepointMapping(_, _, loc) => {
608	            let msg = if loc.is_some() {
609	                "the text was not mapped to a code point"
610	            } else {
611	                "the PDF contains text with missing codepoints"
612	            };
613	            error!(
614	                to_span(*loc),
615	                "{prefix} {msg}";
616	                hint: "for complex scripts like Arabic, it might not be \
617	                       possible to produce a compliant document";
618	            )
619	        }
620	        ValidationError::InvalidCodepointMapping(_, _, c, loc) => {
621	            let msg = if loc.is_some() {
622	                "the text contains"
623	            } else {
624	                "the PDF contains text with"
625	            };
626	            error!(
627	                to_span(*loc),
628	                "{prefix} {msg} the disallowed codepoint `{}`",
629	                c.repr(),
630	            )
631	        }
632	        ValidationError::UnicodePrivateArea(_, _, c, loc) => {
633	            let msg = if loc.is_some() { "the PDF" } else { "the text" };
634	            error!(
635	                to_span(*loc),
636	                "{prefix} {msg} contains the codepoint `{}`", c.repr();
637	                hint: "codepoints from the Unicode private area are \
638	                       forbidden in this export mode";
639	            )
640	        }
641	        ValidationError::RestrictedLicense(f) => error!(
642	            Span::detached(),
643	            "{prefix} license of {} is too restrictive",
644	            display_font(gc.fonts_backward.get(f));
645	            hint: "the font has specified \"Restricted License embedding\" in its \
646	                   metadata";
647	            hint: "restrictive font licenses are prohibited by {} because they limit \
648	                   the suitability for archival",
649	            failing_validators.to_and_list();
650	        ),
651	        ValidationError::Transparency(loc) => {
652	            let span = to_span(*loc);
653	            let hint1 = "try exporting with a different standard that \
654	                         supports transparency";
655	            if loc.is_some() {
656	                if gc.image_spans.contains(&span) {
657	                    error!(
658	                        span, "{prefix} the image contains transparency";
659	                        hint: "{hint1}";
660	                        hint: "or convert the image to a non-transparent one";
661	                        hint: "you might have to convert SVGs into \
662	                               non-transparent bitmap images";
663	                    )
664	                } else {
665	                    error!(
666	                        span, "{prefix} the used fill or stroke has transparency";
667	                        hint: "{hint1}";
668	                        hint: "or don't use colors with transparency in \
669	                               this export mode";
670	                    )
671	                }
672	            } else {
673	                error!(
674	                    span, "{prefix} the PDF contains transparency";
675	                    hint: "{hint1}";
676	                )
677	            }
678	        }
679	        ValidationError::ImageInterpolation(loc) => {
680	            let span = to_span(*loc);
681	            if loc.is_some() {
682	                error!(
683	                    span, "{prefix} the image has smooth scaling";
684	                    hint: "set the `scaling` attribute to `pixelated`";
685	                )
686	            } else {
687	                error!(
688	                    span, "{prefix} an image in the PDF has smooth scaling";
689	                    hint: "set the `scaling` attribute of all images to `pixelated`";
690	                )
691	            }
692	        }
693	        ValidationError::EmbeddedFile(e, s) => {
694	            // We always set the span for attached files, so it cannot be detached.
695	            let span = to_span(*s);
696	            match e {
697	                EmbedError::Existence => {
698	                    error!(
699	                        span, "{prefix} document contains an attached file";
700	                        hint: "file attachments are not supported in this export mode";
701	                    )
702	                }
703	                EmbedError::MissingDate => {
704	                    error!(
705	                        span, "{prefix} document date is missing";
706	                        hint: "the document must have a date when attaching files";
707	                        hint: "`set document(date: none)` must not be used in this case";
708	                    )
709	                }
710	                EmbedError::MissingDescription => {
711	                    error!(span, "{prefix} the file description is missing")
712	                }
713	                EmbedError::MissingMimeType => {
714	                    error!(span, "{prefix} the file mime type is missing")
715	                }
716	            }
717	        }
718	        // The below errors cannot occur yet, only once Typst supports full PDF/A
719	        // and PDF/UA. But let's still add a message just to be on the safe side.
720	        ValidationError::MissingAnnotationAltText(loc) => {
721	            let span = to_span(*loc);
722	            error!(
723	                span, "{prefix} missing annotation alt text";
724	                hint: "please report this as a bug";
725	            )
726	        }
727	        ValidationError::MissingAltText(loc) => {
728	            let span = to_span(*loc);
729	            error!(
730	                span, "{prefix} missing alt text";
731	                hint: "make sure your images and equations have alt text";
732	            )
733	        }
734	        ValidationError::NoDocumentLanguage => error!(
735	            Span::detached(),
736	            "{prefix} missing document language";
737	            hint: "set the language of the document";
738	        ),
739	        // Needs to be set by typst-pdf.
740	        ValidationError::MissingHeadingTitle => error!(
741	            Span::detached(),
742	            "{prefix} missing heading title";
743	            hint: "please report this as a bug";
744	        ),
745	        ValidationError::MissingDocumentOutline => error!(
746	            Span::detached(),
747	            "{prefix} missing document outline";
748	            hint: "please report this as a bug";
749	        ),
750	        ValidationError::MissingTagging => error!(
751	            Span::detached(),
752	            "{prefix} missing document tags";
753	            hint: "please report this as a bug";
754	        ),
755	        ValidationError::NoDocumentTitle => error!(
756	            Span::detached(),
757	            "{prefix} missing document title";
758	            hint: "set the title with `set document(title: [...])`";
759	        ),
760	        ValidationError::MissingDocumentDate => error!(
761	            Span::detached(),
762	            "{prefix} missing document date";
763	            hint: "set the date of the document";
764	        ),
765	        ValidationError::EmbeddedPDF(loc) => {
766	            error!(
767	                to_span(*loc),
768	                "embedding PDFs is currently not supported in this export mode";
769	                hint: "try converting the PDF to an SVG before embedding it";
770	            )
771	        }
772	        ValidationError::RequiresNewerPdfVersion(feature, loc) => {
773	            let span = to_span(*loc);
774	            let message = match feature {
775	                VersionedFeature::StructureOrderTabbing => {
776	                    eco_format!(
777	                        "{prefix} links and other annotations cannot be navigated accessibly in {} files",
778	                        pdf_version.as_str()
779	                    )
780	                }
781	                VersionedFeature::HeaderFooterArtifactSubtypes => {
782	                    eco_format!(
783	                        "{prefix} headers and footers cannot be made accessible in {} files",
784	                        pdf_version.as_str()
785	                    )
786	                }
787	                VersionedFeature::TableHeaderScope => {
788	                    eco_format!(
789	                        "{prefix} table header cell cannot be accessibly tagged in {} files",
790	                        pdf_version.as_str()
791	                    )
792	                }
793	            };
794	
795	            let diagnostic = SourceDiagnostic::error(span, message);
796	
797	            let min_version = feature.minimum_pdf_version();
798	
799	            let mut most_restrictive: Option<(Validator, PdfVersion)> = None;
800	            for validator in gc.options.standards.config.validators() {
801	                let max = validator.max();
802	                if most_restrictive.is_none_or(|(_, prev_max)| prev_max > max) {
803	                    most_restrictive = Some((validator, max));
804	                }
805	            }
806	
807	            let Some((restrictive_validator, max_version)) = most_restrictive else {
808	                // Does not happen in practice: A validator is required to raise
809	                // this error and they always have a maximum version.
810	                return diagnostic;
811	            };
812	
813	            if min_version < max_version {
814	                diagnostic.with_hint(eco_format!(
815	                    "select a version between {} and {}",
816	                    min_version.as_str(),
817	                    max_version.as_str(),
818	                ))
819	            } else if min_version == max_version {
820	                diagnostic
821	                    .with_hint(eco_format!("set the version to {}", min_version.as_str()))
822	            } else {
823	                diagnostic
824	                    .with_hint(eco_format!(
825	                        "PDF version must be at least {} to satisfy {}",
826	                        min_version.as_str(),
827	                        failing_validators.to_and_list(),
828	                    ))
829	                    .with_hint(eco_format!(
830	                        "remove or replace the {} standard, \
831	                         as it prevents PDF versions beyond {}",
832	                        restrictive_validator.as_str(),
833	                        max_version.as_str(),
834	                    ))
835	            }
836	        }
837	    }
838	}
839	
840	/// Convert a krilla location to a span.
841	pub(crate) fn to_span(loc: Option<krilla::surface::Location>) -> Span {
842	    loc.map(Span::from_raw).unwrap_or(Span::detached())
843	}
844	
845	fn collect_named_destinations(
846	    document: &mut Document,
847	    typst_document: &PagedDocument,
848	    anchors: &[(Location, EcoString)],
849	    pic: &PageIndexConverter,
850	) -> FxHashMap<Location, NamedDestination> {
851	    let mut locs_to_names = FxHashMap::default();
852	
853	    // Find all headings that have a label and are the first among other
854	    // headings with the same label.
855	    let mut seen = FxHashSet::default();
856	    let headings = typst_document.introspector().query(&HeadingElem::ELEM.select());
857	    let matches = anchors
858	        .iter()
859	        .map(|(loc, anchor)| (*loc, anchor.to_string()))
860	        .chain(
861	            headings
862	                .iter()
863	                .filter_map(|elem| elem.location().zip(elem.label()))
864	                .map(|(loc, label)| (loc, label.resolve().to_string())),
865	        )
866	        .filter(|(_, name)| seen.insert(name.clone()));
867	
868	    for (loc, name) in matches {
869	        // Only add named destination if page belonging to the position is exported.
870	        let pos = typst_document
871	            .introspector()
872	            .position(loc)
873	            .unwrap_or(PagedPosition::ORIGIN);
874	        if let Some(dest) = crate::link::pos_to_xyz(pic, pos) {
875	            let named = NamedDestination::new(name, dest);
876	            // The option is `None` if the destination is a duplicate which
877	            // should not happen because we filtered them on a set insert above,
878	            // hence the unwrap.
879	            document.register_named_destination(named.clone()).unwrap();
880	            locs_to_names.insert(loc, named);
881	        }
882	    }
883	
884	    locs_to_names
885	}
886	
887	pub(crate) struct PageIndexConverter {
888	    page_indices: FxHashMap<usize, usize>,
889	    skipped_pages: usize,
890	}
891	
892	impl PageIndexConverter {
893	    pub fn new(document: &PagedDocument, options: &PdfOptions) -> Self {
894	        let mut page_indices = FxHashMap::default();
895	        let mut skipped_pages = 0;
896	
897	        for i in 0..document.pages().len() {
898	            if options
899	                .page_ranges
900	                .as_ref()
901	                .is_some_and(|ranges| !ranges.includes_page_index(i))
902	            {
903	                skipped_pages += 1;
904	            } else {
905	                page_indices.insert(i, i - skipped_pages);
906	            }
907	        }
908	
909	        Self { page_indices, skipped_pages }
910	    }
911	
912	    pub(crate) fn has_skipped_pages(&self) -> bool {
913	        self.skipped_pages > 0
914	    }
915	
916	    /// Get the PDF page index of a page index, if it's not excluded.
917	    pub(crate) fn pdf_page_index(&self, page_index: usize) -> Option<usize> {
918	        self.page_indices.get(&page_index).copied()
919	    }
920	}
