1	//! Convert paint types from Typst to krilla.
2	
3	use std::f64::consts::PI;
4	
5	use krilla::color::separation::SeparationSpace;
6	use krilla::color::{self, cmyk, luma, rgb, separation};
7	use krilla::num::NormalizedF32;
8	use krilla::paint::{
9	    Fill, LinearGradient, Pattern, RadialGradient, SpreadMethod, Stop, Stroke,
10	    StrokeDash, SweepGradient,
11	};
12	use krilla::surface::Surface;
13	use typst_library::diag::SourceResult;
14	use typst_library::foundations::Smart;
15	use typst_library::layout::{Abs, Angle, Point, Quadrant, Ratio, Sides, Size, Transform};
16	use typst_library::visualize::{
17	    Color, ColorSpace, DashPattern, FillRule, FixedStroke, Geometry, Gradient, Paint,
18	    ProcessColor, ProcessColorSpace, RelativeTo, Shape, SpotColor, Tiling, WeightedColor,
19	};
20	use typst_utils::Numeric;
21	
22	use crate::convert::{FrameContext, GlobalContext, State, handle_frame};
23	use crate::tags;
24	use crate::util::{
25	    AbsExt, FillRuleExt, LineCapExt, LineJoinExt, SpotColorantToNameExt, TransformExt,
26	};
27	
28	pub(crate) fn convert_fill(
29	    gc: &mut GlobalContext,
30	    paint_: &Paint,
31	    fill_rule_: FillRule,
32	    on_text: bool,
33	    surface: &mut Surface,
34	    state: &State,
35	    shape: Option<&Shape>,
36	) -> SourceResult<Fill> {
37	    let (paint, opacity) =
38	        convert_paint(gc, paint_, on_text, surface, state, shape, false)?;
39	
40	    Ok(Fill {
41	        paint,
42	        rule: fill_rule_.to_krilla(),
43	        opacity: NormalizedF32::new(opacity as f32 / 255.0).unwrap(),
44	    })
45	}
46	
47	pub(crate) fn convert_stroke(
48	    fc: &mut GlobalContext,
49	    stroke: &FixedStroke,
50	    on_text: bool,
51	    surface: &mut Surface,
52	    state: &State,
53	    shape: Option<&Shape>,
54	) -> SourceResult<Stroke> {
55	    let (paint, opacity) =
56	        convert_paint(fc, &stroke.paint, on_text, surface, state, shape, true)?;
57	
58	    Ok(Stroke {
59	        paint,
60	        width: stroke.thickness.to_f32(),
61	        miter_limit: stroke.miter_limit.get() as f32,
62	        line_join: stroke.join.to_krilla(),
63	        line_cap: stroke.cap.to_krilla(),
64	        opacity: NormalizedF32::new(opacity as f32 / 255.0).unwrap(),
65	        dash: stroke.dash.as_ref().map(convert_dash),
66	    })
67	}
68	
69	fn convert_paint(
70	    gc: &mut GlobalContext,
71	    paint: &Paint,
72	    on_text: bool,
73	    surface: &mut Surface,
74	    state: &State,
75	    shape: Option<&Shape>,
76	    include_stroke_in_bbox: bool,
77	) -> SourceResult<(krilla::paint::Paint, u8)> {
78	    let (offset, mut size) = if let Some(s) = shape {
79	        let bbox = s.bbox(include_stroke_in_bbox);
80	        let (mut offset, mut size) = (bbox.min, bbox.size());
81	        // Special handling for rectangles (mirrors gradients for negative sizes)
82	        if let Geometry::Rect(rect) = s.geometry {
83	            if rect.x.signum() < 1.0 {
84	                offset.x += size.x;
85	                size.x *= -1.0;
86	            }
87	            if rect.y.signum() < 1.0 {
88	                offset.y += size.y;
89	                size.y *= -1.0;
90	            }
91	        }
92	        (offset, size)
93	    } else {
94	        (Point::zero(), Size::zero())
95	    };
96	
97	    if size.x.is_zero() {
98	        size.x = Abs::pt(1.0);
99	    }
100	    if size.y.is_zero() {
101	        size.y = Abs::pt(1.0);
102	    }
103	
104	    match paint {
105	        Paint::Solid(c) => {
106	            let (c, a) = convert_solid(c);
107	            Ok((c.into(), a))
108	        }
109	        Paint::Gradient(g) => Ok(convert_gradient(g, on_text, state, size, offset)),
110	        Paint::Tiling(p) => convert_pattern(gc, p, on_text, surface, state),
111	    }
112	}
113	
114	fn convert_solid(color: &Color) -> (color::Color, u8) {
115	    match color {
116	        Color::Process(color) => {
117	            let (color, alpha) = convert_process_solid(*color);
118	            (color.into(), alpha)
119	        }
120	        Color::Spot(color) => (convert_spot(color).into(), 255),
121	    }
122	}
123	
124	fn convert_process_solid(color: ProcessColor) -> (color::RegularColor, u8) {
125	    match color.space() {
126	        ProcessColorSpace::D65Gray => {
127	            let (c, a) = convert_luma(color);
128	            (c.into(), a)
129	        }
130	        ProcessColorSpace::Cmyk => (convert_cmyk(color).into(), 255),
131	        // Convert all other colors in different color spaces into RGB.
132	        _ => {
133	            let (c, a) = convert_rgb(color);
134	            (c.into(), a)
135	        }
136	    }
137	}
138	
139	fn convert_cmyk(color: ProcessColor) -> cmyk::Color {
140	    let components = color.to_space(ProcessColorSpace::Cmyk).to_vec4_u8();
141	
142	    cmyk::Color::new(components[0], components[1], components[2], components[3])
143	}
144	
145	fn convert_rgb(color: ProcessColor) -> (rgb::Color, u8) {
146	    let components = color.to_space(ProcessColorSpace::Srgb).to_vec4_u8();
147	    (rgb::Color::new(components[0], components[1], components[2]), components[3])
148	}
149	
150	fn convert_luma(color: ProcessColor) -> (luma::Color, u8) {
151	    let components = color.to_space(ProcessColorSpace::D65Gray).to_vec4_u8();
152	    (luma::Color::new(components[0]), components[3])
153	}
154	
155	fn convert_spot(color: &SpotColor) -> separation::Color {
156	    separation::Color::new(
157	        (color.tint.get() * 255.0).round() as u8,
158	        SeparationSpace::new(
159	            color.colorant.name.to_krilla(),
160	            convert_process_solid(color.colorant.fallback).0,
161	        ),
162	    )
163	}
164	
165	fn convert_pattern(
166	    gc: &mut GlobalContext,
167	    pattern: &Tiling,
168	    on_text: bool,
169	    surface: &mut Surface,
170	    state: &State,
171	) -> SourceResult<(krilla::paint::Paint, u8)> {
172	    let transform = correct_transform(state, pattern.unwrap_relative(on_text))
173	        .pre_concat(pattern.transform());
174	
175	    let mut stream_builder = surface.stream_builder();
176	    let mut surface = stream_builder.surface();
177	    tags::tiling(gc, &mut surface, pattern.size(), |gc, surface| {
178	        let mut fc = FrameContext::new(None, pattern.frame().size());
179	        handle_frame(
180	            &mut fc,
181	            pattern.frame(),
182	            Sides::splat(Abs::zero()),
183	            None,
184	            surface,
185	            gc,
186	        )
187	    })?;
188	    surface.finish();
189	    let stream = stream_builder.finish();
190	    let pattern = Pattern {
191	        stream,
192	        transform: transform.to_krilla(),
193	        width: (pattern.size().x + pattern.spacing().x).to_pt() as f32,
194	        height: (pattern.size().y + pattern.spacing().y).to_pt() as f32,
195	    };
196	
197	    Ok((pattern.into(), 255))
198	}
199	
200	fn convert_gradient(
201	    gradient: &Gradient,
202	    on_text: bool,
203	    state: &State,
204	    size: Size,
205	    offset: Point,
206	) -> (krilla::paint::Paint, u8) {
207	    let (size, offset) = match gradient.unwrap_relative(on_text) {
208	        RelativeTo::Self_ => (size, offset),
209	        RelativeTo::Parent => (state.container_size(), Point::zero()),
210	    };
211	
212	    let angle = gradient.angle().unwrap_or_else(Angle::zero);
213	    let base_transform = correct_transform(state, gradient.unwrap_relative(on_text));
214	    let stops = convert_gradient_stops(gradient);
215	    match &gradient {
216	        Gradient::Linear(_) => {
217	            let angle = Gradient::correct_aspect_ratio(angle, size.aspect_ratio());
218	            let (sin, cos) = (angle.sin(), angle.cos());
219	
220	            // Scale to edges of unit square.
221	            let factor = cos.abs() + sin.abs();
222	
223	            let (x1, y1) = match angle.quadrant() {
224	                Quadrant::First => (0.0, 0.0),
225	                Quadrant::Second => (1.0, 0.0),
226	                Quadrant::Third => (1.0, 1.0),
227	                Quadrant::Fourth => (0.0, 1.0),
228	            };
229	            let x2 = x1 + (cos * factor) as f32;
230	            let y2 = y1 + (sin * factor) as f32;
231	
232	            let linear = LinearGradient {
233	                x1,
234	                y1,
235	                x2,
236	                y2,
237	                // x and y coordinates are normalized, so need to scale by the size.
238	                transform: base_transform
239	                    .pre_concat(Transform::translate(offset.x, offset.y))
240	                    .pre_concat(Transform::scale(
241	                        Ratio::new(size.x.to_f32() as f64),
242	                        Ratio::new(size.y.to_f32() as f64),
243	                    ))
244	                    .to_krilla(),
245	                spread_method: SpreadMethod::Pad,
246	                stops,
247	                anti_alias: gradient.anti_alias(),
248	            };
249	
250	            (linear.into(), 255)
251	        }
252	        Gradient::Radial(radial) => {
253	            let radial = RadialGradient {
254	                fx: radial.focal_center.x.get() as f32,
255	                fy: radial.focal_center.y.get() as f32,
256	                fr: radial.focal_radius.get() as f32,
257	                cx: radial.center.x.get() as f32,
258	                cy: radial.center.y.get() as f32,
259	                cr: radial.radius.get() as f32,
260	                transform: base_transform
261	                    .pre_concat(Transform::translate(offset.x, offset.y))
262	                    .pre_concat(Transform::scale(
263	                        Ratio::new(size.x.to_f32() as f64),
264	                        Ratio::new(size.y.to_f32() as f64),
265	                    ))
266	                    .to_krilla(),
267	                spread_method: SpreadMethod::Pad,
268	                stops,
269	                anti_alias: gradient.anti_alias(),
270	            };
271	
272	            (radial.into(), 255)
273	        }
274	        Gradient::Conic(conic) => {
275	            // Correct the gradient's angle.
276	            let cx = size.x.to_f32() * conic.center.x.get() as f32;
277	            let cy = size.y.to_f32() * conic.center.y.get() as f32;
278	            let actual_transform = base_transform
279	                // Adjust for the angle.
280	                .pre_concat(Transform::rotate_at(
281	                    angle + Angle::rad(PI),
282	                    Abs::pt(cx as f64),
283	                    Abs::pt(cy as f64),
284	                ))
285	                .pre_concat(Transform::translate(offset.x, offset.y));
286	
287	            let sweep = SweepGradient {
288	                cx,
289	                cy,
290	                start_angle: 0.0,
291	                end_angle: 360.0,
292	                transform: actual_transform.to_krilla(),
293	                spread_method: SpreadMethod::Pad,
294	                stops,
295	                anti_alias: gradient.anti_alias(),
296	            };
297	
298	            (sweep.into(), 255)
299	        }
300	    }
301	}
302	
303	fn convert_gradient_stops(gradient: &Gradient) -> Vec<Stop> {
304	    let mut stops = vec![];
305	
306	    let mut add_single = |color: &Color, offset: Ratio| {
307	        let (color, opacity) = convert_solid(color);
308	
309	        let opacity = NormalizedF32::new((opacity as f32) / 255.0).unwrap();
310	        let offset = NormalizedF32::new(offset.get() as f32).unwrap();
311	        let stop = Stop { offset, color, opacity };
312	        stops.push(stop);
313	    };
314	
315	    // Convert stops.
316	    match &gradient {
317	        Gradient::Linear(_) | Gradient::Radial(_) => {
318	            if let Some(s) = gradient.stops().first() {
319	                add_single(&s.color, s.offset.unwrap());
320	            }
321	
322	            // Create the individual gradient functions for each pair of stops.
323	            for window in gradient.stops().windows(2) {
324	                let (first, second) = (&window[0], &window[1]);
325	
326	                add_single(&first.color, first.offset.unwrap());
327	
328	                // If we have a hue index or are using Oklab, we will create several
329	                // stops in-between to make the gradient smoother without interpolation
330	                // issues with native color spaces.
331	                if second.offset.unwrap() > first.offset.unwrap()
332	                    && (gradient.space().hue_index().is_some()
333	                        || gradient.space()
334	                            == ColorSpace::Process(ProcessColorSpace::Oklab)
335	                        || gradient.space()
336	                            == ColorSpace::Process(ProcessColorSpace::Oklab))
337	                {
338	                    gradient
339	                        .generate_intermediate_stops_for_rgb_interpolation(first, second)
340	                        .for_each(|(color, at)| add_single(&color, at));
341	                }
342	            }
343	
344	            if let Some(last) = gradient.stops().last() {
345	                add_single(&last.color, last.offset.unwrap());
346	            }
347	        }
348	        Gradient::Conic(conic) => {
349	            if let Some((c, t)) = conic.stops.first() {
350	                add_single(c, *t);
351	            }
352	
353	            for window in conic.stops.windows(2) {
354	                let ((c0, t0), (c1, t1)) = (&window[0], &window[1]);
355	
356	                // Precision:
357	                // - On an even color, insert a stop every 90deg.
358	                // - For a hue-based color space, insert 200 stops minimum.
359	                // - On any other, insert 20 stops minimum.
360	                let max_dt = if c0 == c1 {
361	                    0.25
362	                } else if conic.space.hue_index().is_some() {
363	                    0.005
364	                } else {
365	                    0.05
366	                };
367	
368	                let mut t_x = t0.get();
369	                let dt = (t1.get() - t0.get()).min(max_dt);
370	
371	                // Special casing for sharp gradients.
372	                if t0 == t1 {
373	                    add_single(c1, *t1);
374	                    continue;
375	                }
376	
377	                while t_x < t1.get() {
378	                    let t_next = (t_x + dt).min(t1.get());
379	
380	                    // The current progress in the current window.
381	                    let t = |t| (t - t0.get()) / (t1.get() - t0.get());
382	
383	                    let c_next = Color::mix_iter(
384	                        [
385	                            WeightedColor::new(c0.clone(), 1.0 - t(t_next)),
386	                            WeightedColor::new(c1.clone(), t(t_next)),
387	                        ],
388	                        Smart::Custom(conic.space.clone()),
389	                    )
390	                    .unwrap();
391	
392	                    add_single(&c_next, Ratio::new(t_next));
393	                    t_x = t_next;
394	                }
395	
396	                add_single(c1, *t1);
397	            }
398	        }
399	    }
400	
401	    stops
402	}
403	
404	fn convert_dash(dash: &DashPattern<Abs, Abs>) -> StrokeDash {
405	    StrokeDash {
406	        array: dash.array.iter().map(|e| e.to_f32()).collect(),
407	        offset: dash.phase.to_f32(),
408	    }
409	}
410	
411	fn correct_transform(state: &State, relative: RelativeTo) -> Transform {
412	    // In krilla, if we have a shape with a transform and a complex paint,
413	    // then the paint will inherit the transform of the shape.
414	    match relative {
415	        // Because of the above, we don't need to apply an additional transform here.
416	        RelativeTo::Self_ => Transform::identity(),
417	        // Because of the above, we need to first reverse the transform that will be
418	        // applied from the shape, and then re-apply the transform that is used for
419	        // the next parent container.
420	        RelativeTo::Parent => state
421	            .transform()
422	            .invert()
423	            .unwrap()
424	            .pre_concat(state.container_transform()),
425	    }
426	}
