1	use std::hash::{Hash, Hasher};
2	use std::sync::{Arc, OnceLock};
3	
4	use ecow::eco_format;
5	use image::{DynamicImage, EncodableLayout, GenericImageView, Rgba};
6	use krilla::image::{BitsPerComponent, CustomImage, ImageColorspace};
7	use krilla::pdf::PdfDocument;
8	use krilla::surface::Surface;
9	use krilla_svg::{SurfaceExt, SvgSettings};
10	use typst_library::diag::{At, SourceResult};
11	use typst_library::foundations::Smart;
12	use typst_library::layout::{Abs, Angle, Ratio, Size, Transform};
13	use typst_library::visualize::{
14	    ExchangeFormat, Image, ImageKind, ImageScaling, PdfImage, RasterFormat, RasterImage,
15	};
16	use typst_syntax::Span;
17	use typst_utils::defer;
18	
