83	/// A wrapper around `RasterImage` so that we can implement `CustomImage`.
84	#[derive(Clone)]
85	struct PdfRasterImage(Arc<PdfRasterImageInner>);
86	
87	/// The internal representation of a [`PdfRasterImage`].
88	struct PdfRasterImageInner {
89	    /// The original, underlying raster image.
90	    raster: RasterImage,
91	    /// The alpha channel of the raster image, if existing.
92	    alpha_channel: OnceLock<Option<Vec<u8>>>,
93	    /// A (potentially) converted version of the dynamic image stored `raster` that is
94	    /// guaranteed to either be in luma8 or rgb8, and thus can be used for the
95	    /// `color_channel` method of `CustomImage`.
96	    actual_dynamic: OnceLock<Arc<DynamicImage>>,
97	}
98	
99	impl PdfRasterImage {
100	    /// Wraps a raster image.
101	    pub fn new(raster: RasterImage) -> Self {
102	        Self(Arc::new(PdfRasterImageInner {
103	            raster,
104	            alpha_channel: OnceLock::new(),
105	            actual_dynamic: OnceLock::new(),
106	        }))
107	    }
108	}
109	
110	impl Hash for PdfRasterImage {
111	    fn hash<H: Hasher>(&self, state: &mut H) {
112	        // `alpha_channel` and `actual_dynamic` are generated from the underlying `RasterImage`,
113	        // so this is enough. Since `raster` is prehashed, this is also very cheap.
114	        self.0.raster.hash(state);
115	    }
116	}
117	
118	impl CustomImage for PdfRasterImage {
119	    fn color_channel(&self) -> &[u8] {
120	        self.0
121	            .actual_dynamic
122	            .get_or_init(|| {
123	                let dynamic = self.0.raster.dynamic();
124	                let channel_count = dynamic.color().channel_count();
125	
126	                match (dynamic.as_ref(), channel_count) {
127	                    // Pure luma8 or rgb8 image, can use it directly.
128	                    (DynamicImage::ImageLuma8(_), _) => dynamic.clone(),
129	                    (DynamicImage::ImageRgb8(_), _) => dynamic.clone(),
130	                    // Grey-scale image, convert to luma8.
131	                    (_, 1 | 2) => Arc::new(DynamicImage::ImageLuma8(dynamic.to_luma8())),
132	                    // Anything else, convert to rgb8.
133	                    _ => Arc::new(DynamicImage::ImageRgb8(dynamic.to_rgb8())),
134	                }
135	            })
136	            .as_bytes()
137	    }
138	
139	    fn alpha_channel(&self) -> Option<&[u8]> {
140	        self.0
141	            .alpha_channel
142	            .get_or_init(|| {
143	                self.0.raster.dynamic().color().has_alpha().then(|| {
144	                    self.0
145	                        .raster
146	                        .dynamic()
147	                        .pixels()
148	                        .map(|(_, _, Rgba([_, _, _, a]))| a)
149	                        .collect()
150	                })
151	            })
152	            .as_ref()
153	            .map(|v| &**v)
154	    }
155	
156	    fn bits_per_component(&self) -> BitsPerComponent {
157	        BitsPerComponent::Eight
158	    }
159	
160	    fn size(&self) -> (u32, u32) {
161	        (self.0.raster.width(), self.0.raster.height())
162	    }
163	
164	    fn icc_profile(&self) -> Option<&[u8]> {
165	        if matches!(
166	            self.0.raster.dynamic().as_ref(),
167	            DynamicImage::ImageLuma8(_)
168	                | DynamicImage::ImageLumaA8(_)
169	                | DynamicImage::ImageRgb8(_)
170	                | DynamicImage::ImageRgba8(_)
171	        ) {
172	            self.0.raster.icc().map(|b| b.as_bytes())
173	        } else {
174	            // In all other cases, the dynamic will be converted into RGB8 or LUMA8, so the ICC
175	            // profile may become invalid, and thus we don't include it.
176	            None
177	        }
178	    }
179	
180	    fn color_space(&self) -> ImageColorspace {
181	        // Remember that we convert all images to either RGB or luma.
182	        if self.0.raster.dynamic().color().has_color() {
183	            ImageColorspace::Rgb
184	        } else {
185	            ImageColorspace::Luma
186	        }
187	    }
188	}
