190	#[comemo::memoize]
191	fn convert_raster(
192	    raster: RasterImage,
193	    interpolate: bool,
194	) -> Result<krilla::image::Image, String> {
195	    if let RasterFormat::Exchange(ExchangeFormat::Jpg) = raster.format() {
196	        let image_data: Arc<dyn AsRef<[u8]> + Send + Sync> =
197	            Arc::new(raster.data().clone());
198	        let icc_profile = raster.icc().map(|i| {
199	            let i: Arc<dyn AsRef<[u8]> + Send + Sync> = Arc::new(i.clone());
200	            i
201	        });
202	
203	        krilla::image::Image::from_jpeg_with_icc(
204	            image_data.into(),
205	            icc_profile.map(|i| i.into()),
206	            interpolate,
207	        )
208	    } else {
209	        krilla::image::Image::from_custom(PdfRasterImage::new(raster), interpolate)
210	    }
211	}
212	
213	#[comemo::memoize]
214	fn convert_pdf(pdf: &PdfImage) -> PdfDocument {
215	    PdfDocument::new(pdf.document().pdf().clone())
216	}
217	
218	fn exif_transform(image: &RasterImage, size: Size) -> (Transform, Size) {
219	    // For JPEGs, we want to apply the EXIF orientation as a transformation
220	    // because we don't recode them. For other formats, the transform is already
221	    // baked into the dynamic image data.
222	    if image.format() != RasterFormat::Exchange(ExchangeFormat::Jpg) {
223	        return (Transform::identity(), size);
224	    }
225	
226	    let base = |hp: bool, vp: bool, mut base_ts: Transform, size: Size| {
227	        if hp {
228	            // Flip horizontally in-place.
229	            base_ts = base_ts.pre_concat(
230	                Transform::scale(-Ratio::one(), Ratio::one())
231	                    .pre_concat(Transform::translate(-size.x, Abs::zero())),
232	            );
233	        }
234	
235	        if vp {
236	            // Flip vertically in-place.
237	            base_ts = base_ts.pre_concat(
238	                Transform::scale(Ratio::one(), -Ratio::one())
239	                    .pre_concat(Transform::translate(Abs::zero(), -size.y)),
240	            );
241	        }
242	
243	        base_ts
244	    };
245	
246	    let no_flipping =
247	        |hp: bool, vp: bool| (base(hp, vp, Transform::identity(), size), size);
248	
249	    let with_flipping = |hp: bool, vp: bool| {
250	        let base_ts = Transform::rotate_at(Angle::deg(90.0), Abs::zero(), Abs::zero())
251	            .pre_concat(Transform::scale(Ratio::one(), -Ratio::one()));
252	        let inv_size = Size::new(size.y, size.x);
253	        (base(hp, vp, base_ts, inv_size), inv_size)
254	    };
255	
256	    match image.exif_rotation() {
257	        Some(2) => no_flipping(true, false),
258	        Some(3) => no_flipping(true, true),
