100	pub fn tiling<T>(
101	    gc: &mut GlobalContext,
102	    surface: &mut Surface,
103	    tiling_size: Size,
104	    f: impl FnOnce(&mut GlobalContext, &mut Surface) -> T,
105	) -> T {
106	    if disabled(gc) {
107	        return f(gc, surface);
108	    }
109	
110	    let prev = gc.tags.in_tiling;
111	    gc.tags.in_tiling = true;
112	    let mark_artifact = gc.tags.tree.parent_artifact().is_none();
113	    if mark_artifact {
114	        let bbox = kg::Rect::from_ltrb(
115	            0.0,
116	            0.0,
117	            tiling_size.x.to_pt() as f32,
118	            tiling_size.y.to_pt() as f32,
119	        );
120	        surface.start_tagged(ContentTag::Artifact(Artifact::new(
121	            if gc.options.standards.config.version() == PdfVersion::Pdf17
122	                && bbox.is_none()
123	            {
124	                // PDF 1.7 cannot tolerate empty bounding boxes for background
125	                // artifacts.
126	                ArtifactType::Other
127	            } else {
128	                ArtifactType::Background
129	            },
130	            bbox,
131	        )));
132	    }
133	
134	    let res = f(gc, surface);
135	
136	    if mark_artifact {
137	        surface.end_tagged();
138	    }
139	    gc.tags.in_tiling = prev;
140	
141	    res
