112	    /// NOTE: this needs to be kept in sync with [`Groups::break_group`].
113	    pub fn breakable(&self, kind: &GroupKind) -> BreakOpportunity {
114	        use BreakOpportunity::*;
115	        match kind {
116	            GroupKind::Root(..) => Never,
117	            GroupKind::Artifact(..) => Always(BreakPriority::Span),
118	            GroupKind::LogicalParent(..) => Never,
119	            GroupKind::LogicalChild(..) => Never,
120	            GroupKind::Outline(..) => Never,
121	            GroupKind::OutlineEntry(..) => Never,
122	            GroupKind::Table(..) => Never,
123	            GroupKind::TableCell(..) => Never,
124	            GroupKind::Grid(..) => Never,
125	            GroupKind::GridCell(..) => Never,
126	            GroupKind::List(..) => Never,
127	            GroupKind::ListItemLabel(..) => Never,
128	            GroupKind::ListItemBody(..) => Never,
129	            GroupKind::TermsItemLabel(..) => Never,
130	            GroupKind::TermsItemBody(..) => Never,
131	            GroupKind::BibEntry(..) => Never,
132	            GroupKind::FigureWrapper(..) => Never,
133	            GroupKind::Figure(..) => Never,
134	            GroupKind::FigureCaption(..) => Never,
135	            GroupKind::Image(..) => Never,
136	            GroupKind::Formula(..) => Never,
137	            GroupKind::Link(..) => NoPdfUa(BreakPriority::Span),
138	            GroupKind::CodeBlock(..) => Never,
139	            GroupKind::CodeBlockLine(..) => Never,
140	            GroupKind::Par(..) => NoPdfUa(BreakPriority::Par),
141	            GroupKind::TextAttr(_) => Always(BreakPriority::TextAttr),
142	            GroupKind::Transparent => Never,
143	            GroupKind::Standard(tag, ..) => match self.tags.get(*tag) {
144	                TagKind::Part(_) => Never,
145	                TagKind::Article(_) => Never,
146	                TagKind::Section(_) => Never,
147	                TagKind::Div(_) => Never,
148	                TagKind::BlockQuote(_) => Never,
149	                TagKind::Caption(_) => Never,
150	                TagKind::TOC(_) => Never,
151	                TagKind::TOCI(_) => Never,
152	                TagKind::Index(_) => Never,
153	                TagKind::P(_) => NoPdfUa(BreakPriority::Par),
154	                TagKind::Hn(_) => Never,
155	                TagKind::L(_) => Never,
156	                TagKind::LI(_) => Never,
157	                TagKind::Lbl(_) => Never,
158	                TagKind::LBody(_) => Never,
159	                TagKind::Table(_) => Never,
160	                TagKind::TR(_) => Never,
161	                TagKind::TH(_) => Never,
162	                TagKind::TD(_) => Never,
163	                TagKind::THead(_) => Never,
164	                TagKind::TBody(_) => Never,
165	                TagKind::TFoot(_) => Never,
166	                TagKind::Span(_) => Always(BreakPriority::Span),
167	                TagKind::InlineQuote(_) => Never,
168	                TagKind::Note(_) => Never,
169	                TagKind::Reference(_) => NoPdfUa(BreakPriority::Span),
170	                TagKind::BibEntry(_) => Never,
171	                TagKind::Code(_) => NoPdfUa(BreakPriority::Span),
172	                TagKind::Link(_) => NoPdfUa(BreakPriority::Span),
173	                TagKind::Annot(_) => Never,
174	                TagKind::Figure(_) => Never,
175	                TagKind::Formula(_) => Never,
176	                TagKind::Form(_) => Never,
177	                TagKind::NonStruct(_) => Never,
178	                TagKind::Datetime(_) => Never,
179	                TagKind::Terms(_) => Never,
180	                TagKind::Title(_) => Never,
181	                TagKind::Strong(_) => Always(BreakPriority::Span),
182	                TagKind::Em(_) => Always(BreakPriority::Span),
183	            },
184	        }
185	    }
