187	    /// NOTE: this needs to be kept in sync with [`Groups::breakable`].
188	    pub fn break_group(&mut self, id: GroupId, new_parent: GroupId) -> GroupId {
189	        let group = self.get(id);
190	        let span = group.span;
191	
192	        let new_kind = match &group.kind {
193	            GroupKind::Artifact(ty) => GroupKind::Artifact(*ty),
194	            GroupKind::Link(elem, _) => GroupKind::Link(elem.clone(), None),
195	            GroupKind::Par(_) => GroupKind::Par(None),
196	            GroupKind::TextAttr(attr) => GroupKind::TextAttr(attr.clone()),
197	            GroupKind::Standard(old, _) => {
198	                let tag = self.tags.get(*old).clone();
199	                let new = self.tags.push(tag);
200	                GroupKind::Standard(new, None)
201	            }
202	            GroupKind::Root(..)
203	            | GroupKind::LogicalParent(..)
204	            | GroupKind::LogicalChild(..)
205	            | GroupKind::Outline(..)
206	            | GroupKind::OutlineEntry(..)
207	            | GroupKind::Table(..)
208	            | GroupKind::TableCell(..)
209	            | GroupKind::Grid(..)
210	            | GroupKind::GridCell(..)
211	            | GroupKind::List(..)
212	            | GroupKind::ListItemLabel(..)
213	            | GroupKind::ListItemBody(..)
214	            | GroupKind::TermsItemLabel(..)
215	            | GroupKind::TermsItemBody(..)
216	            | GroupKind::BibEntry(..)
217	            | GroupKind::FigureWrapper(..)
218	            | GroupKind::Figure(..)
219	            | GroupKind::FigureCaption(..)
220	            | GroupKind::Image(..)
221	            | GroupKind::Formula(..)
222	            | GroupKind::CodeBlock(..)
223	            | GroupKind::CodeBlockLine(..)
224	            | GroupKind::Transparent => unreachable!(),
225	        };
226	        self.list.push(Group::weak(new_parent, span, new_kind))
227	    }
228	}
