263	/// These methods are the only way to insert nested groups in the
264	/// [`Group::nodes`] list.
265	impl Groups {
266	    /// Create a new group with a standard tag and push it into the parent.
267	    pub fn push_tag(&mut self, parent: GroupId, tag: impl Into<TagKind>) -> GroupId {
268	        let tag_id = self.tags.push(tag);
269	        let kind = GroupKind::Standard(tag_id, None);
270	        let id = self.list.push(Group::new(parent, Span::detached(), kind));
271	        self.get_mut(parent).nodes.push(TagNode::Group(id));
272	        id
273	    }
274	
275	    /// Prepend multiple existing group to the start of the parent.
276	    #[cfg_attr(debug_assertions, track_caller)]
277	    pub fn prepend_groups(&mut self, parent: GroupId, children: &[GroupId]) {
278	        debug_assert!({
279	            children.iter().all(|child| self.check_ancestor(parent, *child))
280	        });
281	        self.get_mut(parent)
282	            .nodes
283	            .splice(..0, children.iter().map(|id| TagNode::Group(*id)));
284	    }
285	
286	    /// Append an existing group to the end of the parent.
287	    #[cfg_attr(debug_assertions, track_caller)]
288	    pub fn push_group(&mut self, parent: GroupId, child: GroupId) {
289	        debug_assert!(self.check_ancestor(parent, child));
290	        self.get_mut(parent).nodes.push(TagNode::Group(child));
291	    }
292	
293	    /// Append multiple existing groups to the end of the parent.
294	    #[cfg_attr(debug_assertions, track_caller)]
295	    pub fn push_groups(&mut self, parent: GroupId, children: &[GroupId]) {
296	        debug_assert!({
297	            children.iter().all(|child| self.check_ancestor(parent, *child))
298	        });
299	        self.get_mut(parent)
300	            .nodes
301	            .extend(children.iter().map(|id| TagNode::Group(*id)));
302	    }
303	
304	    /// Check whether the child's [`Group::parent`] is either the `parent` or an
305	    /// ancestor of the `parent`.
306	    fn check_ancestor(&self, parent: GroupId, child: GroupId) -> bool {
307	        let group = self.get(child);
308	
309	        // Logical children that don't inherit their parent's styles have their
310	        // parent set to the original location they appeared in the tree,
311	        // but will be inserted into the correct logical parent.
312	        if let GroupKind::LogicalChild(Inherit::No, _) = group.kind {
313	            return true;
314	        }
315	
316	        let ancestor = group.parent;
317	        let mut current = parent;
318	        while current != GroupId::INVALID {
319	            if current == ancestor {
320	                return true;
321	            }
322	            current = self.get(current).parent;
323	        }
324	        false
325	    }
326	}
