361	#[derive(Debug)]
362	pub struct Group {
363	    /// The parent of this group. Must not be the direct parent in the concrete
364	    /// tag tree that will be built. But it must be an ancestor in the resulting
365	    /// tree. For example for a [`GroupKind::TableCell`] this will point to the
366	    /// parent [`GroupKind::Table`] even though the concrete tag tree will have
367	    /// intermediate [`TagKind::TR`] or [`TagKind::TBody`] groups in the
368	    /// generated `nodes`.
369	    pub parent: GroupId,
370	    pub span: Span,
371	    pub kind: GroupKind,
372	    /// Only allow mutating this list through the API, to ensure the parent
373	    /// will be set for child groups.
374	    nodes: Vec<TagNode>,
375	    /// Whether this group was split off another group as a result of
376	    /// overlapping tags. A weak group will be omitted if it has no children.
377	    pub weak: bool,
378	}
379	
380	impl Group {
381	    fn new(parent: GroupId, span: Span, kind: GroupKind) -> Self {
382	        Group { parent, span, kind, nodes: Vec::new(), weak: false }
383	    }
384	
385	    fn weak(parent: GroupId, span: Span, kind: GroupKind) -> Self {
386	        Group { parent, span, kind, nodes: Vec::new(), weak: true }
387	    }
388	
389	    pub fn nodes(&self) -> &[TagNode] {
390	        &self.nodes
391	    }
392	
393	    pub fn push_leaf(&mut self, id: Identifier) {
394	        self.nodes.push(TagNode::Leaf(id));
395	    }
396	
397	    pub fn push_annotation(&mut self, annot_id: AnnotationId) {
398	        self.nodes.push(TagNode::Annotation(annot_id));
399	    }
400	
401	    pub fn push_text(&mut self, new_attrs: ResolvedTextAttrs, text_id: Identifier) {
402	        if new_attrs.is_empty() {
403	            self.push_leaf(text_id);
404	            return;
405	        }
406	
407	        let last_node = self.nodes.last_mut();
408	        if let Some(TagNode::Text(prev_attrs, nodes)) = last_node
409	            && *prev_attrs == new_attrs
410	        {
411	            nodes.push(text_id);
412	        } else {
413	            self.nodes.push(TagNode::Text(new_attrs, vec![text_id]));
414	        }
415	    }
416	
417	    pub fn pop_node(&mut self) -> Option<TagNode> {
418	        self.nodes.pop()
419	    }
420	}
