496	impl GroupKind {
497	    pub fn is_artifact(&self) -> bool {
498	        matches!(*self, GroupKind::Artifact(_))
499	    }
500	
501	    pub fn is_link(&self) -> bool {
502	        matches!(self, Self::Link(..))
503	    }
504	
505	    pub fn to_artifact(
506	        &self,
507	        options: &PdfOptions,
508	        page_size: Option<Size>,
509	    ) -> Option<Artifact> {
510	        let GroupKind::Artifact(artifact) = *self else { return None };
511	
512	        if options.standards.config.version() == PdfVersion::Pdf17
513	            && artifact == ArtifactType::Background
514	        {
515	            // Background artifacts were introduced in PDF 1.7. However,
516	            // they require a bounding box there, which may not be readily
517	            // available throughout Typst. In PDF 2.0, this requirement is
518	            // dropped. Hence, to not have to make up a bounding box, we
519	            // explicitly override the type as `Other` for PDF 1.7. For PDF
520	            // 1.6 and below, Krilla handles the type mapping. For PDF 2.0
521	            // and above, we use the correct artifact type.
522	            return Some(match page_size {
523	                Some(size) => {
524	                    let bbox = kg::Rect::from_ltrb(
525	                        0.0,
526	                        0.0,
527	                        size.x.to_pt() as f32,
528	                        size.y.to_pt() as f32,
529	                    )
530	                    .unwrap();
531	                    Artifact { kind: ArtifactType::Background, bbox: Some(bbox) }
532	                }
533	                None => Artifact::with_kind(ArtifactType::Other),
534	            });
535	        }
536	
537	        Some(Artifact::with_kind(artifact))
538	    }
539	
540	    pub fn as_link(&self) -> Option<&Packed<LinkMarker>> {
541	        if let Self::Link(v, ..) = self { Some(v) } else { None }
542	    }
543	
544	    pub fn as_table(&self) -> Option<TableId> {
545	        if let Self::Table(id, ..) = self { Some(*id) } else { None }
546	    }
547	
548	    pub fn as_grid(&self) -> Option<GridId> {
549	        if let Self::Grid(id, ..) = self { Some(*id) } else { None }
550	    }
551	
552	    pub fn as_list(&self) -> Option<ListId> {
553	        if let Self::List(id, ..) = self { Some(*id) } else { None }
554	    }
