556	    pub fn bbox(&self) -> Option<BBoxId> {
557	        match self {
558	            GroupKind::Table(_, id, _) => Some(*id),
559	            GroupKind::Figure(_, id, _) => Some(*id),
560	            GroupKind::FigureCaption(id, _) => Some(*id),
561	            GroupKind::Image(_, id, _) => Some(*id),
562	            GroupKind::Formula(_, id, _) => Some(*id),
563	            _ => None,
564	        }
565	    }
566	
567	    pub fn lang(&self) -> Option<Option<Locale>> {
568	        Some(match *self {
569	            GroupKind::Root(lang) => lang,
570	            GroupKind::Artifact(_) => return None,
571	            GroupKind::LogicalParent(_) => return None,
572	            GroupKind::LogicalChild(_, _) => return None,
573	            GroupKind::Outline(_, lang) => lang,
574	            GroupKind::OutlineEntry(_, lang) => lang,
575	            GroupKind::Table(_, _, lang) => lang,
576	            GroupKind::TableCell(_, _, lang) => lang,
577	            GroupKind::Grid(_, lang) => lang,
578	            GroupKind::GridCell(_, lang) => lang,
579	            GroupKind::List(_, _, lang) => lang,
580	            GroupKind::ListItemLabel(lang) => lang,
581	            GroupKind::ListItemBody(lang) => lang,
582	            GroupKind::TermsItemLabel(lang) => lang,
583	            GroupKind::TermsItemBody(_, lang) => lang,
584	            GroupKind::BibEntry(lang) => lang,
585	            GroupKind::FigureWrapper(_) => return None,
586	            GroupKind::Figure(_, _, lang) => lang,
587	            GroupKind::FigureCaption(_, lang) => lang,
588	            GroupKind::Image(_, _, lang) => lang,
589	            GroupKind::Formula(_, _, lang) => lang,
590	            GroupKind::Link(_, lang) => lang,
591	            GroupKind::CodeBlock(lang) => lang,
592	            GroupKind::CodeBlockLine(lang) => lang,
593	            GroupKind::Par(lang) => lang,
594	            GroupKind::TextAttr(_) => return None,
595	            GroupKind::Transparent => return None,
596	            GroupKind::Standard(_, lang) => lang,
597	        })
598	    }
599	
600	    pub fn lang_mut(&mut self) -> Option<&mut Option<Locale>> {
601	        Some(match self {
602	            GroupKind::Root(lang) => lang,
603	            GroupKind::Artifact(_) => return None,
604	            GroupKind::LogicalParent(_) => return None,
605	            GroupKind::LogicalChild(_, _) => return None,
606	            GroupKind::Outline(_, lang) => lang,
607	            GroupKind::OutlineEntry(_, lang) => lang,
608	            GroupKind::Table(_, _, lang) => lang,
609	            GroupKind::TableCell(_, _, lang) => lang,
610	            GroupKind::Grid(_, lang) => lang,
611	            GroupKind::GridCell(_, lang) => lang,
612	            GroupKind::List(_, _, lang) => lang,
613	            GroupKind::ListItemLabel(lang) => lang,
614	            GroupKind::ListItemBody(lang) => lang,
615	            GroupKind::TermsItemLabel(lang) => lang,
616	            GroupKind::TermsItemBody(_, lang) => lang,
617	            GroupKind::BibEntry(lang) => lang,
618	            GroupKind::FigureWrapper(_) => return None,
619	            GroupKind::Figure(_, _, lang) => lang,
620	            GroupKind::FigureCaption(_, lang) => lang,
621	            GroupKind::Image(_, _, lang) => lang,
622	            GroupKind::Formula(_, _, lang) => lang,
623	            GroupKind::Link(_, lang) => lang,
624	            GroupKind::CodeBlock(lang) => lang,
625	            GroupKind::CodeBlockLine(lang) => lang,
626	            GroupKind::Par(lang) => lang,
627	            GroupKind::TextAttr(_) => return None,
628	            GroupKind::Transparent => return None,
629	            GroupKind::Standard(_, lang) => lang,
630	        })
631	    }
632	
633	    /// Whether this group is a semantic parent or child group. Non-semantic
634	    /// groups will be ignored when searching the tree hierarchy.
635	    pub fn is_semantic(&self) -> bool {
636	        // While paragraphs do have a semantic meaning, they are automatically
637	        // generated and may interfere with other more strongly structured
638	        // nesting groups. For example the `TermsItemLabel` might be wrapped by
639	        // a paragraph, out of which it is moved into the parent `LI`.
640	        !matches!(
641	            self,
642	            GroupKind::Transparent
643	                | GroupKind::LogicalParent(..)
644	                | GroupKind::LogicalChild(..)
645	                | GroupKind::TextAttr(_)
646	                | GroupKind::Par(_)
647	        )
648	    }
649	}
