67	    /// Find the highest artifact ancestor in the tree.
68	    pub fn parent_artifact(&self) -> Option<Artifact> {
69	        let (_, ty) = self.state.current_artifact?;
70	        Some(ty)
71	    }
72	
73	    /// Find the lowest ancestor with a bounding box in the tree.
74	    pub fn parent_bbox(&mut self) -> Option<&mut BBoxCtx> {
75	        let id = *self.state.bbox_stack.last()?;
76	        Some(self.ctx.bboxes.get_mut(id))
77	    }
78	
79	    pub fn assert_finished_traversal(&self) -> HintedStrResult<()> {
80	        assert_internal(
81	            self.prog_cursor + 1 == self.progressions.len(),
82	            "tree traversal didn't complete properly",
83	        )?;
84	        assert_internal(
85	            self.break_cursor == self.breaks.len(),
86	            "tree traversal didn't complete properly",
87	        )?;
88	        assert_internal(
89	            self.unfinished_cursor == self.unfinished.len(),
90	            "tree traversal didn't complete properly",
91	        )?;
92	        Ok(())
93	    }
94	}
95	
96	/// A stack of traversal states, the topmost entry represents the current state
97	/// in the tree. New stack entries are pushed on when entering a logical child
98	/// and popped off when leaving one.
99	struct TraversalStates {
100	    /// Always non-empty.
101	    stack: Vec<TraversalState>,
102	}
103	
104	impl TraversalStates {
105	    fn new() -> Self {
106	        Self { stack: vec![TraversalState::new()] }
107	    }
108	
109	    fn push(&mut self, state: TraversalState) {
110	        self.stack.push(state);
111	    }
112	
113	    fn pop(&mut self) {
114	        self.stack.pop();
115	    }
116	}
117	
118	impl std::ops::Deref for TraversalStates {
119	    type Target = TraversalState;
120	
121	    fn deref(&self) -> &Self::Target {
122	        self.stack.last().unwrap()
123	    }
124	}
125	
126	impl std::ops::DerefMut for TraversalStates {
127	    fn deref_mut(&mut self) -> &mut Self::Target {
128	        self.stack.last_mut().unwrap()
129	    }
130	}
131	
132	/// Stores frequently accessed properties about the current tree traversal
133	/// position. This is an optimization to avoid searching all ancestors; instead
134	/// this is updated on each step.
135	struct TraversalState {
136	    /// The highest artifact ancestor in the tree.
137	    current_artifact: Option<(GroupId, Artifact)>,
138	    /// The stack of ancestors that have a [`GroupKind::bbox`].
139	    bbox_stack: Vec<BBoxId>,
140	    /// The stack of text attributes.
141	    text_attrs: TextAttrs,
142	}
143	
144	impl TraversalState {
145	    fn new() -> Self {
146	        Self {
147	            current_artifact: None,
148	            bbox_stack: Vec::new(),
149	            text_attrs: TextAttrs::new(),
150	        }
151	    }
152	
153	    /// Update the traversal state when moving out of a group.
154	    fn pop_group(&mut self, surface: &mut Surface, id: GroupId, group: &Group) {
155	        if self.current_artifact.take_if(|(i, _)| *i == id).is_some() {
156	            surface.end_tagged();
157	        }
158	        if let Some(id) = group.kind.bbox() {
159	            self.bbox_stack.pop_if(|i| *i == id);
160	        }
161	        self.text_attrs.pop(id);
162	    }
163	}
164	
165	/// Marks a point where the entries on the stack were split up.
166	#[derive(Debug, Copy, Clone)]
167	struct Break {
168	    /// The index of the progression at which point the broken up groups need to
169	    /// be closed.
170	    prog_idx: u32,
171	    /// The number of groups which have to be closed, from the previous
172	    /// group upwards in the parent hierarchy.
173	    num_closed: u16,
174	    /// The number of groups which have to be closed, from the next group
175	    /// upwards in the parent hierarchy.
176	    num_opened: u16,
177	}
178	
179	/// Marks a point at the end of a logical child or parent where the stack was
180	/// not fully closed, and the open groups were handled in the next logical
181	/// child.
182	#[derive(Debug, Copy, Clone)]
183	struct Unfinished {
184	    /// The index of the progression at which point the broken up groups need to
185	    /// be closed.
186	    prog_idx: u32,
187	    group_to_close: GroupId,
188	}
189	
190	pub fn step_start_tag(gc: &mut GlobalContext, fc: &FrameContext, surface: &mut Surface) {
191	    let Some((prev, next)) = step(&mut gc.tags.tree) else { return };
192	
193	    if let Some(brk) = consume_break(&mut gc.tags.tree) {
194	        step_break(gc, fc, surface, prev, next, brk);
195	    } else {
196	        open_group(
197	            &gc.tags.tree.groups,
198	            &mut gc.tags.tree.state,
199	            fc,
200	            gc.options,
201	            surface,
202	            next,
203	        );
204	    }
205	}
206	
207	pub fn step_end_tag(gc: &mut GlobalContext, fc: &FrameContext, surface: &mut Surface) {
208	    let Some((prev, next)) = step(&mut gc.tags.tree) else { return };
209	
210	    if let Some(brk) = consume_break(&mut gc.tags.tree) {
211	        step_break(gc, fc, surface, prev, next, brk);
212	    } else {
213	        close_group(&mut gc.tags.tree, surface, prev);
214	    }
215	}
216	
217	/// This can move to a completely different position in the tree.
218	pub fn enter_logical_child(
219	    gc: &mut GlobalContext,
220	    fc: &FrameContext,
221	    surface: &mut Surface,
222	) {
223	    let Some((_, next)) = step(&mut gc.tags.tree) else { return };
224	
225	    // Close any artifact in the previous location.
226	    if gc.tags.tree.parent_artifact().is_some() {
227	        surface.end_tagged();
228	    }
229	
230	    // Compute the traversal state for the new location in the tree and push it.
231	    let mut new_state = TraversalState::new();
232	    let mut current = next;
233	    let rev_iter = std::iter::from_fn(|| {
234	        if current == GroupId::INVALID {
235	            return None;
236	        }
237	        let id = current;
238	        let group = gc.tags.tree.groups.get(id);
239	        current = group.parent;
240	        Some((id, group))
241	    });
242	    open_multiple_groups(&mut new_state, fc, gc.options, surface, rev_iter);
243	
244	    gc.tags.tree.state.push(new_state);
245	}
246	
247	/// This moves back to the previous location in the tree.
248	pub fn leave_logical_child(tree: &mut Tree, surface: &mut Surface) {
249	    let Some((prev, _)) = step(tree) else { return };
250	
251	    // The stack within a logical child, could also be unfinished, in
252	    // which case a `BreakKind::Unfinished` is inserted to close the
253	    // `LogicalChild` group.
254	    if let Some(unfinished) = consume_unfinished(tree) {
255	        close_group(tree, surface, unfinished.group_to_close);
256	    } else {
257	        close_group(tree, surface, prev);
258	    }
259	
260	    // Close any artifact in the logical child.
261	    if tree.parent_artifact().is_some() {
262	        surface.end_tagged();
263	    }
264	
265	    tree.state.pop();
266	
267	    // Reopen any artifact in the restored location of the tree.
268	    if let Some(ty) = tree.parent_artifact() {
269	        surface.start_tagged(ContentTag::Artifact(ty));
270	    }
271	}
272	
273	fn step(tree: &mut Tree) -> Option<(GroupId, GroupId)> {
274	    let prev = tree.current();
275	    tree.prog_cursor += 1;
276	    let next = tree.current();
277	
278	    // We didn't move into a new group, no actions are necessary.
279	    if prev == next {
280	        return None;
281	    }
282	
283	    Some((prev, next))
284	}
285	
286	fn consume_break(tree: &mut Tree) -> Option<Break> {
287	    let brk = *tree.breaks.get(tree.break_cursor)?;
288	    if brk.prog_idx as usize == tree.prog_cursor {
289	        tree.break_cursor += 1;
290	        return Some(brk);
291	    }
292	    None
293	}
294	
295	fn consume_unfinished(tree: &mut Tree) -> Option<Unfinished> {
296	    let unfinished = *tree.unfinished.get(tree.unfinished_cursor)?;
297	    if unfinished.prog_idx as usize == tree.prog_cursor {
298	        tree.unfinished_cursor += 1;
299	        return Some(unfinished);
300	    }
301	    None
302	}
303	
304	fn step_break(
305	    gc: &mut GlobalContext,
306	    fc: &FrameContext,
307	    surface: &mut Surface,
308	    prev: GroupId,
309	    next: GroupId,
310	    brk: Break,
311	) {
312	    // Close groups.
313	    let mut current = prev;
314	    for _ in 0..brk.num_closed {
315	        current = close_group(&mut gc.tags.tree, surface, current);
316	    }
317	
318	    // Open groups.
319	    let mut current = next;
320	    let rev_iter = std::iter::from_fn(|| {
321	        let id = current;
322	        let group = gc.tags.tree.groups.get(id);
323	        current = group.parent;
324	        Some((id, group))
325	    });
326	    open_multiple_groups(
327	        &mut gc.tags.tree.state,
328	        fc,
329	        gc.options,
330	        surface,
331	        rev_iter.take(brk.num_opened as usize),
332	    );
333	}
334	
335	fn open_group(
336	    groups: &Groups,
337	    state: &mut TraversalState,
338	    fc: &FrameContext,
339	    options: &PdfOptions,
340	    surface: &mut Surface,
341	    id: GroupId,
342	) {
343	    let group = groups.get(id);
344	    if state.current_artifact.is_none()
345	        && let Some(ty) = group.kind.to_artifact(options, fc.page_size())
346	    {
347	        state.current_artifact = Some((id, ty));
348	        surface.start_tagged(ContentTag::Artifact(ty));
349	    }
350	    if let Some(bbox) = &group.kind.bbox() {
351	        state.bbox_stack.push(*bbox);
352	    }
353	    if let GroupKind::TextAttr(attr) = &group.kind {
354	        state.text_attrs.push(id, attr.clone());
355	    }
356	}
357	
358	/// Since the groups need to be opened in order, but we can only iterate the
359	/// parent hierarchy from bottom to top, this cannot simply call [`open_group`].
360	fn open_multiple_groups<'a>(
361	    state: &mut TraversalState,
362	    fc: &FrameContext,
363	    options: &PdfOptions,
364	    surface: &mut Surface,
365	    rev_iter: impl Iterator<Item = (GroupId, &'a Group)>,
366	) {
367	    let mut new_artifact = None;
368	    let bbox_start = state.bbox_stack.len();
369	    let text_attr_start = state.text_attrs.len();
370	
371	    for (id, group) in rev_iter {
372	        if let Some(ty) = group.kind.to_artifact(options, fc.page_size()) {
373	            new_artifact = Some((id, ty));
374	        }
375	        if let Some(bbox) = group.kind.bbox() {
376	            state.bbox_stack.insert(bbox_start, bbox);
377	        }
378	        if let GroupKind::TextAttr(attr) = &group.kind {
379	            state.text_attrs.insert(text_attr_start, id, attr.clone());
380	        }
381	    }
382	
383	    if state.current_artifact.is_none()
384	        && let Some((_, ty)) = new_artifact
385	    {
386	        state.current_artifact = new_artifact;
387	        surface.start_tagged(ContentTag::Artifact(ty));
388	    }
389	}
390	
391	fn close_group(tree: &mut Tree, surface: &mut Surface, id: GroupId) -> GroupId {
392	    let group = tree.groups.get(id);
393	    let direct_parent = group.parent;
394	    let semantic_parent = semantic_parent(tree, direct_parent);
395	
396	    tree.state.pop_group(surface, id, group);
397	
398	    match &group.kind {
399	        GroupKind::Root(_) => unreachable!(),
400	        GroupKind::Artifact(_) => {
401	            tree.groups.push_group(direct_parent, id);
402	        }
403	        GroupKind::LogicalParent(elem) => {
404	            let loc = elem.location().unwrap();
405	            // Insert logical children when closing the logical parent, so they
406	            // are at the end of the group. In some cases there might be
407	            // multiple parent groups with the same location, only insert the
408	            // children for the first parent group.
409	            if let Some(located) = tree.groups.by_loc(&loc)
410	                && located.id == id
411	                && let Some(children) = tree.logical_children.get(&loc)
412	            {
413	                tree.groups.push_groups(id, children);
414	            }
415	
416	            tree.groups.push_group(direct_parent, id);
417	        }
418	        GroupKind::LogicalChild(inherit, logical_parent) => {
419	            if *inherit == Inherit::No {
420	                // If this logical child doesn't inherit its parent's styles and
421	                // is not inside of an artifact, inserting it into a parent that
422	                // is inside of an artifact would mean the content will be
423	                // discarded. If that's the case, ignore the logical parent
424	                // structure and insert it wherever it appeared in the frame
425	                // tree.
426	                let logical_parent_is_in_artifact = 'artifact: {
427	                    let mut current = tree.groups.get(*logical_parent).parent;
428	                    while current != GroupId::INVALID {
429	                        let group = tree.groups.get(current);
430	                        if group.kind.is_artifact() {
431	                            break 'artifact true;
432	                        }
433	                        current = group.parent;
434	                    }
435	                    false
436	                };
437	
438	                if tree.parent_artifact().is_none() && logical_parent_is_in_artifact {
439	                    tree.groups.push_group(direct_parent, id);
440	                }
441	            } else if !matches!(
442	                tree.groups.get(direct_parent).kind,
443	                GroupKind::LogicalParent(_)
444	            ) {
445	                // `GroupKind::LogicalParent` handles inserting of children at its
446	                // end, see above. Children of table/grid cells are always ordered
447	                // correctly and are treated a little bit differently.
448	                tree.groups.push_group(direct_parent, id);
449	            }
450	        }
451	        GroupKind::Outline(..) => {
452	            tree.groups.push_group(direct_parent, id);
453	        }
454	        GroupKind::OutlineEntry(entry, _) => {
455	            if let GroupKind::Outline(outline, _) = tree.groups.get(semantic_parent).kind
456	            {
457	                let outline_ctx = tree.ctx.outlines.get_mut(outline);
458	                let entry = entry.clone();
459	                tree.groups.get_mut(id).parent = semantic_parent;
460	                outline_ctx.insert(&mut tree.groups, semantic_parent, entry, id);
461	            } else {
462	                tree.groups.push_group(direct_parent, id);
463	            }
464	        }
465	        GroupKind::Table(..) => {
466	            tree.groups.push_group(direct_parent, id);
467	        }
468	        &GroupKind::TableCell(ref cell, tag, _) => {
469	            let cell = cell.clone();
470	            if let Some(table) = move_into(tree, semantic_parent, id, GroupKind::as_table)
471	            {
472	                let table_ctx = tree.ctx.tables.get_mut(table);
473	                table_ctx.insert(&cell, tag, id);
474	            } else {
475	                // Avoid panicking, the nesting will be validated later.
476	                tree.groups.push_group(direct_parent, id);
477	            }
478	        }
479	        GroupKind::Grid(..) => {
480	            tree.groups.push_group(direct_parent, id);
481	        }
482	        GroupKind::GridCell(cell, _) => {
483	            let cell = cell.clone();
484	            if let Some(grid) = move_into(tree, semantic_parent, id, GroupKind::as_grid) {
485	                let grid_ctx = tree.ctx.grids.get_mut(grid);
486	                grid_ctx.insert(&cell, id);
487	            } else {
488	                // Avoid panicking, the nesting will be validated later.
489	                tree.groups.push_group(direct_parent, id);
490	            }
491	        }
492	        GroupKind::List(..) => {
493	            tree.groups.push_group(direct_parent, id);
494	        }
495	        GroupKind::ListItemLabel(..) => {
496	            if let Some(list) = move_into(tree, semantic_parent, id, GroupKind::as_list) {
497	                let list_ctx = tree.ctx.lists.get_mut(list);
498	                list_ctx.push_label(&mut tree.groups, semantic_parent, id);
499	            } else {
500	                // Avoid panicking, the nesting will be validated later.
501	                tree.groups.push_group(direct_parent, id);
502	            }
503	        }
504	        GroupKind::ListItemBody(..) => {
505	            if let Some(list) = move_into(tree, semantic_parent, id, GroupKind::as_list) {
506	                let list_ctx = tree.ctx.lists.get_mut(list);
507	                list_ctx.push_body(&mut tree.groups, semantic_parent, id);
508	            } else {
509	                // Avoid panicking, the nesting will be validated later.
510	                tree.groups.push_group(direct_parent, id);
511	            }
512	        }
513	        GroupKind::TermsItemLabel(..) => {
514	            if let GroupKind::TermsItemBody(lbl, _) =
515	                &mut tree.groups.get_mut(semantic_parent).kind
516	            {
517	                *lbl = Some(id);
518	            } else {
519	                // Avoid panicking, the nesting will be validated later.
520	                tree.groups.push_group(direct_parent, id);
521	            }
522	        }
523	        &GroupKind::TermsItemBody(lbl, ..) => {
524	            if let Some(list) = move_into(tree, semantic_parent, id, GroupKind::as_list) {
525	                let list_ctx = tree.ctx.lists.get_mut(list);
526	                if let Some(lbl) = lbl {
527	                    tree.groups.get_mut(lbl).parent = semantic_parent;
528	                    list_ctx.push_label(&mut tree.groups, semantic_parent, lbl);
529	                }
530	                list_ctx.push_body(&mut tree.groups, semantic_parent, id);
531	            } else {
532	                // Avoid panicking, the nesting will be validated later.
533	                tree.groups.push_group(direct_parent, id);
534	            }
535	        }
536	        GroupKind::BibEntry(..) => {
537	            if let Some(list) = move_into(tree, semantic_parent, id, GroupKind::as_list) {
538	                let list_ctx = tree.ctx.lists.get_mut(list);
539	                list_ctx.push_bib_entry(&mut tree.groups, semantic_parent, id);
540	            } else {
541	                // Avoid panicking, the nesting will be validated later.
542	                tree.groups.push_group(direct_parent, id);
543	            }
544	        }
545	        GroupKind::FigureWrapper(..) => unreachable!("only generated below"),
546	        GroupKind::Figure(figure, ..) => {
547	            // Insert the wrapper.
548	            let kind = GroupKind::FigureWrapper(*figure);
549	            let wrapper = tree.groups.new_virtual(direct_parent, group.span, kind);
550	            tree.groups.push_group(direct_parent, wrapper);
551	
552	            // Push the figure into the wrapper.
553	            tree.groups.get_mut(id).parent = wrapper;
554	            tree.groups.push_group(wrapper, id);
555	        }
556	        GroupKind::FigureCaption(..) => {
557	            if let GroupKind::Figure(figure, ..) = tree.groups.get(semantic_parent).kind {
558	                let figure_ctx = tree.ctx.figures.get_mut(figure);
559	                figure_ctx.captions.push(id);
560	            } else {
561	                tree.groups.push_group(direct_parent, id);
562	            }
563	        }
564	        GroupKind::Image(..) => {
565	            tree.groups.push_group(direct_parent, id);
566	        }
567	        GroupKind::Formula(..) => {
568	            tree.groups.push_group(direct_parent, id);
569	        }
570	        GroupKind::Link(..) => {
571	            // Wrap link in reference tag if inside an outline entry.
572	            let mut parent = direct_parent;
573	            if let GroupKind::OutlineEntry(..) = tree.groups.get(direct_parent).kind {
574	                parent = tree.groups.push_tag(parent, Tag::Reference);
575	            }
576	            tree.groups.push_group(parent, id);
577	        }
578	        GroupKind::CodeBlock(..) => {
579	            tree.groups.push_group(direct_parent, id);
580	        }
581	        GroupKind::CodeBlockLine(..) => {
582	            tree.groups.push_group(direct_parent, id);
583	        }
584	        GroupKind::Par(..) => {
585	            tree.groups.push_group(direct_parent, id);
586	        }
587	        GroupKind::TextAttr(..) => {
588	            tree.groups.push_group(direct_parent, id);
589	        }
590	        GroupKind::Transparent => {
591	            tree.groups.push_group(direct_parent, id);
592	        }
593	        GroupKind::Standard(..) => {
594	            tree.groups.push_group(direct_parent, id);
595	        }
596	    }
597	
598	    direct_parent
599	}
600	
601	fn move_into<T>(
602	    tree: &mut Tree,
603	    semantic_parent: GroupId,
604	    child: GroupId,
605	    f: impl FnOnce(&GroupKind) -> Option<T>,
606	) -> Option<T> {
607	    let res = f(&tree.groups.get(semantic_parent).kind);
608	    if res.is_some() {
609	        tree.groups.get_mut(child).parent = semantic_parent;
610	    }
611	    res
612	}
613	
614	fn semantic_parent(tree: &Tree, direct_parent: GroupId) -> GroupId {
615	    let mut parent = direct_parent;
616	    loop {
617	        let group = tree.groups.get(parent);
618	        if group.kind.is_semantic() {
619	            return parent;
620	        }
621	
622	        parent = group.parent;
623	    }
624	}
