24	pub enum TagNode {
25	    Group(GroupId),
26	    Leaf(Identifier),
27	    /// Allows inserting a annotation into the tag tree.
28	    /// Currently used for [`krilla::page::Page::add_tagged_annotation`].
29	    Annotation(AnnotationId),
30	    /// If the attributes are non-empty this will resolve to a [`Tag::Span`],
31	    /// otherwise the items are inserted directly.
32	    Text(ResolvedTextAttrs, Vec<Identifier>),
33	}
