35	struct Resolver<'a> {
36	    options: &'a PdfOptions,
37	    ctx: &'a Ctx,
38	    groups: &'a IdVec<Group>,
39	    tags: &'a mut TagStorage,
40	    annotations: &'a mut Annotations,
41	    last_heading_level: Option<NonZeroU16>,
42	    flatten: bool,
43	    errors: EcoVec<SourceDiagnostic>,
44	}
