46	impl Resolver<'_> {
47	    fn with_flatten<T>(&mut self, flatten: bool, f: impl FnOnce(&mut Self) -> T) -> T {
48	        let prev = self.flatten;
49	        self.flatten |= flatten;
50	        let res = f(self);
51	        self.flatten = prev;
52	        res
53	    }
54	}
