56	pub fn resolve(gc: &mut GlobalContext) -> SourceResult<(Option<Locale>, TagTree)> {
57	    gc.tags.tree.assert_finished_traversal().at(Span::detached())?;
58	
59	    if !disabled(gc) {
60	        context::finish(&mut gc.tags.tree);
61	    }
62	
63	    let root = gc.tags.tree.groups.list.get(GroupId::ROOT);
64	    let GroupKind::Root(mut doc_lang) = root.kind else { unreachable!() };
65	
66	    if disabled(gc) {
67	        return Ok((doc_lang, TagTree::new()));
68	    }
69	
70	    let mut resolver = Resolver {
71	        options: gc.options,
72	        ctx: &gc.tags.tree.ctx,
73	        groups: &gc.tags.tree.groups.list,
74	        tags: &mut gc.tags.tree.groups.tags,
75	        annotations: &mut gc.tags.annotations,
76	        last_heading_level: None,
77	        flatten: false,
78	        errors: std::mem::take(&mut gc.tags.tree.errors),
79	    };
80	
81	    let mut accum = Accumulator::root();
82	    accum.reserve(root.nodes().len());
83	
84	    for child in root.nodes() {
85	        resolve_node(&mut resolver, &mut doc_lang, &mut None, &mut accum, child);
86	    }
87	
88	    if !resolver.errors.is_empty() {
89	        return Err(resolver.errors);
90	    }
91	
92	    let children = accum.finish();
93	
94	    Ok((doc_lang, TagTree::from(children)))
95	}
96	
97	/// Resolves nodes into an accumulator.
98	fn resolve_node(
99	    rs: &mut Resolver,
100	    parent_lang: &mut Option<Locale>,
101	    parent_bbox: &mut Option<BBoxCtx>,
102	    accum: &mut Accumulator,
103	    node: &TagNode,
104	) {
105	    match &node {
106	        TagNode::Group(id) => {
107	            resolve_group_node(rs, parent_lang, parent_bbox, accum, *id);
108	        }
109	        TagNode::Leaf(identifier) => {
110	            accum.push(Node::Leaf(*identifier));
111	        }
112	        TagNode::Annotation(id) => {
113	            accum.push(rs.annotations.take(*id));
114	        }
115	        TagNode::Text(attrs, ids) => {
116	            resolve_text(accum, attrs, ids);
117	        }
118	    }
119	}
120	
121	fn resolve_group_node(
122	    rs: &mut Resolver,
123	    parent_lang: &mut Option<Locale>,
124	    parent_bbox: &mut Option<BBoxCtx>,
125	    accum: &mut Accumulator,
126	    id: GroupId,
127	) {
128	    let group = rs.groups.get(id);
129	
130	    let tag = build_group_tag(rs, group);
131	    let mut lang = group.kind.lang().filter(|_| tag.is_some());
132	    let mut bbox = rs.ctx.bbox(&group.kind).cloned();
133	
134	    // If this group doesn't produce a tag, don't create a nested accumulator
135	    // and push the children directly into the parent.
136	    let mut nested_children = None;
137	    let children = if let Some(tag) = &tag {
138	        let nesting = element_kind(tag);
139	        nested_children.insert(accum.nest(nesting))
140	    } else {
141	        &mut *accum
142	    };
143	
144	    // If a tag has an alternative description specified, flatten the children
145	    // tags, only retaining link tags, because they are required. The inner tags
146	    // won't be ingested by AT anyway, but would still have to comply with all
147	    // rules, which can be annoying.
148	    let flatten = tag.as_ref().is_some_and(|t| t.alt_text().is_some());
149	    rs.with_flatten(flatten, |rs| {
150	        let lang = lang.as_mut().unwrap_or(parent_lang);
151	        let bbox = if bbox.is_some() { &mut bbox } else { &mut *parent_bbox };
152	
153	        // In PDF 1.7, don't include artifacts in the tag tree. In PDF 2.0
154	        // this might become an `Artifact` tag.
155	        if group.kind.is_artifact() {
156	            for child in group.nodes() {
157	                resolve_artifact_node(rs, bbox, child);
158	            }
159	        } else {
160	            children.reserve(group.nodes().len());
161	            for child in group.nodes() {
162	                resolve_node(rs, lang, bbox, children, child);
163	            }
164	        }
165	    });
166	
167	    // Try to propagate the group's language to the parent tag.
168	    let lang = util::propagate_lang(parent_lang, lang.flatten());
169	
170	    // Update the parent bbox.
171	    if let Some((parent, child)) = parent_bbox.as_mut().zip(bbox.as_ref()) {
172	        parent.expand_page(child);
173	    }
174	
175	    // If this isn't a tagged group the children have already been inserted
176	    // directly into the parent
177	    let Some((mut tag, nested_children)) = tag.zip(nested_children) else { return };
178	
179	    // Omit the weak group if it is empty.
180	    let nodes = nested_children.finish();
181	    if group.weak && nodes.is_empty() {
182	        return;
183	    }
184	
185	    tag.set_lang(lang.map(|l| l.rfc_3066().to_string()));
186	    if let Some(bbox) = bbox {
187	        match &mut tag {
188	            TagKind::Table(tag) => tag.set_bbox(bbox.to_krilla()),
189	            TagKind::Figure(tag) => tag.set_bbox(bbox.to_krilla()),
190	            TagKind::Formula(tag) => tag.set_bbox(bbox.to_krilla()),
191	            _ => (),
192	        }
193	    }
194	
195	    if rs.options.accessibility_validator().is_some() {
196	        validate_children(rs, &tag, &nodes);
197	    }
198	
199	    accum.push(Node::Group(kt::TagGroup::with_children(tag, nodes)));
200	}
201	
202	fn resolve_text(
203	    accum: &mut Accumulator,
204	    attrs: &ResolvedTextAttrs,
205	    children: &[kt::Identifier],
206	) {
207	    enum Prev<'a> {
208	        Children(&'a [kt::Identifier]),
209	        Group(kt::TagGroup),
210	    }
211	
212	    impl Prev<'_> {
213	        fn into_nodes(self) -> Vec<Node> {
214	            match self {
215	                Prev::Children(ids) => ids.iter().map(|id| Node::Leaf(*id)).collect(),
216	                Prev::Group(group) => vec![Node::Group(group)],
217	            }
218	        }
219	    }
220	
221	    let mut prev = Prev::Children(children);
222	    if attrs.script.is_some() || attrs.background.is_some() || attrs.deco.is_some() {
223	        let tag = Tag::Span
224	            .with_line_height(attrs.script.map(|s| s.lineheight))
225	            .with_baseline_shift(attrs.script.map(|s| s.baseline_shift))
226	            .with_background_color(attrs.background.flatten())
227	            .with_text_decoration_type(attrs.deco.map(|d| d.kind.to_krilla()))
228	            .with_text_decoration_color(attrs.deco.and_then(|d| d.color))
229	            .with_text_decoration_thickness(attrs.deco.and_then(|d| d.thickness));
230	
231	        let group = kt::TagGroup::with_children(tag, prev.into_nodes());
232	        prev = Prev::Group(group);
233	    }
234	    if attrs.strong == Some(true) {
235	        let group = kt::TagGroup::with_children(Tag::Strong, prev.into_nodes());
236	        prev = Prev::Group(group);
237	    }
238	    if attrs.emph == Some(true) {
239	        let group = kt::TagGroup::with_children(Tag::Em, prev.into_nodes());
240	        prev = Prev::Group(group);
241	    }
242	
243	    match prev {
244	        Prev::Group(group) => accum.push(Node::Group(group)),
245	        Prev::Children(ids) => accum.extend(ids.iter().map(|id| Node::Leaf(*id))),
246	    }
247	}
248	
249	/// Currently only done to resolve bounding boxes.
250	fn resolve_artifact_node(
251	    rs: &mut Resolver,
252	    parent_bbox: &mut Option<BBoxCtx>,
253	    node: &TagNode,
254	) {
255	    match &node {
256	        TagNode::Group(id) => {
257	            let group = rs.groups.get(*id);
258	            let mut bbox = rs.ctx.bbox(&group.kind).cloned();
259	
260	            {
261	                let bbox = if bbox.is_some() { &mut bbox } else { &mut *parent_bbox };
262	                for child in group.nodes() {
263	                    resolve_artifact_node(rs, bbox, child);
264	                }
265	            }
266	
267	            // Update the parent bbox.
268	            if let Some((parent, child)) = parent_bbox.as_mut().zip(bbox.as_ref()) {
269	                parent.expand_page(child);
270	            }
271	        }
272	        TagNode::Leaf(..) => (),
273	        TagNode::Annotation(..) => (),
274	        TagNode::Text(..) => (),
275	    }
276	}
277	
278	fn build_group_tag(rs: &mut Resolver, group: &Group) -> Option<TagKind> {
279	    let tag = match &group.kind {
280	        GroupKind::Root(_) => unreachable!(),
281	        GroupKind::Artifact(_) => return None,
282	        GroupKind::LogicalParent(_) => return None,
283	        GroupKind::LogicalChild(_, _) => return None,
284	        GroupKind::Outline(_, _) => Tag::TOC.into(),
285	        GroupKind::OutlineEntry(_, _) => Tag::TOCI.into(),
286	        GroupKind::Table(id, _, _) => rs.ctx.tables.get(*id).build_tag(),
287	        GroupKind::TableCell(_, tag, _) => rs.tags.take(*tag),
288	        GroupKind::Grid(_, _) => Tag::Div.into(),
289	        GroupKind::GridCell(_, _) => Tag::Div.into(),
290	        GroupKind::List(_, numbering, _) => Tag::L(*numbering).into(),
291	        GroupKind::ListItemLabel(_) => Tag::Lbl.into(),
292	        GroupKind::ListItemBody(_) => Tag::LBody.into(),
293	        GroupKind::TermsItemLabel(_) => Tag::Lbl.into(),
294	        GroupKind::TermsItemBody(_, _) => Tag::LBody.into(),
295	        GroupKind::BibEntry(_) => Tag::BibEntry.into(),
296	        GroupKind::FigureWrapper(id) => rs.ctx.figures.get(*id).build_wrapper_tag()?,
297	        GroupKind::Figure(id, _, _) => rs.ctx.figures.get(*id).build_tag()?,
298	        GroupKind::FigureCaption(_, _) => Tag::Caption.into(),
299	        GroupKind::Image(image, _, _) => {
300	            let alt = image.alt.opt_ref().map(Into::into);
301	            Tag::Figure(alt).with_placement(Some(kt::Placement::Block)).into()
302	        }
303	        GroupKind::Formula(equation, _, _) => {
304	            let alt = equation.alt.opt_ref().map(Into::into);
305	            let placement = equation.block.val().then_some(kt::Placement::Block);
306	            Tag::Formula(alt).with_placement(placement).into()
307	        }
308	        GroupKind::Link(_, _) => Tag::Link.into(),
309	        GroupKind::CodeBlock(_) => {
310	            Tag::Code.with_placement(Some(kt::Placement::Block)).into()
311	        }
312	        GroupKind::CodeBlockLine(_) => Tag::P.into(),
313	        GroupKind::Par(_) => Tag::P.into(),
314	        GroupKind::TextAttr(_) => return None,
315	        GroupKind::Transparent => return None,
316	        GroupKind::Standard(tag, _) => rs.tags.take(*tag),
317	    };
318	
319	    let tag = tag.with_location(Some(group.span.into_raw()));
320	
321	    if rs.flatten && !group.kind.is_link() {
322	        return None;
323	    }
324	
325	    // Check that no heading levels were skipped.
326	    if let TagKind::Hn(tag) = &tag {
327	        let prev_level = rs.last_heading_level.map_or(0, |l| l.get());
328	        let next_level = tag.level();
329	        if let Some(accessibility) = rs.options.accessibility_validator()
330	            && next_level.get().saturating_sub(prev_level) > 1
331	        {
332	            let span = to_span(tag.as_any().location);
333	            let validator = accessibility.as_str();
334	            if rs.last_heading_level.is_none() {
335	                rs.errors.push(error!(
336	                    span,
337	                    "{validator} error: the first heading must be of level 1",
338	                ));
339	            } else {
340	                rs.errors.push(error!(
341	                    span,
342	                    "{validator} error: skipped from heading level \
343	                     {prev_level} to {next_level}";
344	                    hint: "heading levels must be consecutive";
345	                ));
346	            }
347	        }
348	
349	        rs.last_heading_level = Some(next_level);
350	    }
351	
352	    Some(tag)
353	}
354	
355	#[derive(Copy, Clone, Eq, PartialEq)]
356	enum ElementKind {
357	    Grouping,
358	    Block,
359	    Table,
360	    Inline,
361	}
362	
363	fn element_kind(tag: &TagKind) -> ElementKind {
364	    match tag {
365	        TagKind::Part(_)
366	        | TagKind::Article(_)
367	        | TagKind::Section(_)
368	        | TagKind::Div(_)
369	        | TagKind::BlockQuote(_)
370	        | TagKind::Caption(_)
371	        | TagKind::TOC(_)
372	        | TagKind::TOCI(_)
373	        | TagKind::Index(_)
374	        | TagKind::NonStruct(_) => ElementKind::Grouping,
375	        TagKind::P(_)
376	        | TagKind::Hn(_)
377	        | TagKind::L(_)
378	        | TagKind::LI(_)
379	        | TagKind::Lbl(_)
380	        | TagKind::LBody(_)
381	        | TagKind::Table(_) => ElementKind::Block,
382	        TagKind::THead(_)
383	        | TagKind::TBody(_)
384	        | TagKind::TFoot(_)
385	        | TagKind::TR(_)
386	        | TagKind::TH(_)
387	        | TagKind::TD(_) => ElementKind::Table,
388	        TagKind::Span(_)
389	        | TagKind::InlineQuote(_)
390	        | TagKind::Note(_)
391	        | TagKind::Reference(_)
392	        | TagKind::BibEntry(_)
393	        | TagKind::Code(_)
394	        | TagKind::Link(_)
395	        | TagKind::Annot(_)
396	        | TagKind::Figure(_)
397	        | TagKind::Formula(_)
398	        | TagKind::Form(_) => ElementKind::Inline,
399	        // Mapped to `Span`.
400	        TagKind::Datetime(_) => ElementKind::Inline,
401	        // Mapped to `Part`.
402	        TagKind::Terms(_) => ElementKind::Grouping,
403	        // Mapped to `P`.
404	        TagKind::Title(_) => ElementKind::Block,
405	        // Mapped to `Span`.
406	        TagKind::Strong(_) | TagKind::Em(_) => ElementKind::Inline,
407	    }
408	}
409	
410	fn validate_children(rs: &mut Resolver, tag: &TagKind, children: &[Node]) {
411	    match tag {
412	        TagKind::TOC(_) => validate_children_groups(rs, tag, children, |child| {
413	            matches!(child, TagKind::TOC(_) | TagKind::TOCI(_))
414	        }),
415	        TagKind::TOCI(_) => validate_children_groups(rs, tag, children, |child| {
416	            matches!(
417	                child,
418	                TagKind::TOC(_)
419	                    | TagKind::Reference(_)
420	                    | TagKind::NonStruct(_)
421	                    | TagKind::P(_)
422	                    | TagKind::Lbl(_)
423	            )
424	        }),
425	        TagKind::L(_) => validate_children_groups(rs, tag, children, |child| {
426	            matches!(child, TagKind::Caption(_) | TagKind::L(_) | TagKind::LI(_))
427	        }),
428	        TagKind::LI(_) => validate_children_groups(rs, tag, children, |child| {
429	            matches!(child, TagKind::Lbl(_) | TagKind::LBody(_))
430	        }),
431	        TagKind::Table(_) => validate_children_groups(rs, tag, children, |child| {
432	            matches!(
433	                child,
434	                TagKind::Caption(_)
435	                    | TagKind::THead(_)
436	                    | TagKind::TBody(_)
437	                    | TagKind::TFoot(_)
438	                    | TagKind::TR(_)
439	            )
440	        }),
441	        TagKind::THead(_) | TagKind::TBody(_) | TagKind::TFoot(_) => {
442	            validate_children_groups(rs, tag, children, |child| {
443	                matches!(child, TagKind::TR(_))
444	            });
445	        }
446	        TagKind::TR(_) => validate_children_groups(rs, tag, children, |child| {
447	            matches!(child, TagKind::TD(_) | TagKind::TH(_))
448	        }),
449	        _ => (),
450	    }
451	}
452	
453	fn validate_children_groups(
454	    rs: &mut Resolver,
455	    parent: &TagKind,
456	    children: &[Node],
457	    mut is_valid: impl FnMut(&TagKind) -> bool,
458	) {
459	    let parent_span = to_span(parent.location());
460	
461	    let mut caption_spans = SmallVec::<[_; 3]>::new();
462	    let mut contains_leaf_nodes = false;
463	    for node in children {
464	        let Node::Group(child) = node else {
465	            contains_leaf_nodes = true;
466	            continue;
467	        };
468	
469	        if !is_valid(&child.tag) {
470	            let validator = rs.options.standards.config.validators().to_comma_list();
471	            let span = to_span(child.tag.location()).or(parent_span);
472	            let parent = tag_name(parent);
473	            let child = tag_name(&child.tag);
474	            rs.errors.push(error!(
475	                span,
476	                "{validator} error: invalid {parent} structure";
477	                hint: "{parent} may not contain {child}";
478	                hint: "this is probably caused by a show rule";
479	            ));
480	        } else if matches!(&child.tag, TagKind::Caption(_)) {
481	            caption_spans.push(to_span(child.tag.location()));
482	        }
483	    }
484	
485	    if caption_spans.len() > 1 {
486	        let validator = rs.options.standards.config.validators().to_comma_list();
487	        let parent = tag_name(parent);
488	        let child = tag_name(&Tag::Caption.into());
489	
490	        let caption_error = |span| {
491	            error!(
492	                span,
493	                "{validator} error: invalid {parent} structure";
494	                hint: "{parent} may not contain multiple {child} tags";
495	                hint: "avoid manually calling `figure.caption`";
496	            )
497	        };
498	        if caption_spans.iter().all(|s| !s.is_detached()) {
499	            rs.errors.extend(caption_spans.into_iter().map(caption_error));
500	        } else {
501	            rs.errors.push(caption_error(parent_span));
502	        }
503	    }
504	
505	    if contains_leaf_nodes {
506	        let validator = rs.options.standards.config.validators().to_comma_list();
507	        let parent = tag_name(parent);
508	        rs.errors.push(error!(
509	            parent_span,
510	            "{validator} error: invalid {parent} structure";
511	            hint: "{parent} may not contain marked content directly";
512	            hint: "this is probably caused by a show rule";
513	        ));
514	    }
515	}
516	
517	fn tag_name(tag: &TagKind) -> &'static str {
518	    match tag {
519	        TagKind::Part(_) => "part (Part)",
520	        TagKind::Article(_) => "article (Art)",
521	        TagKind::Section(_) => "section (Section)",
522	        TagKind::Div(_) => "division (Div)",
523	        TagKind::BlockQuote(_) => "block quote (BlockQuote)",
524	        TagKind::Caption(_) => "caption (Caption)",
525	        TagKind::TOC(_) => "outline (TOC)",
526	        TagKind::TOCI(_) => "outline entry (TOCI)",
527	        TagKind::Index(_) => "index (Index)",
528	        TagKind::P(_) => "paragraph (P)",
529	        TagKind::Hn(_) => "heading (Hn)",
530	        TagKind::L(_) => "list (L)",
531	        TagKind::LI(_) => "list item (LI)",
532	        TagKind::Lbl(_) => "label (Lbl)",
533	        TagKind::LBody(_) => "list body (LBody)",
534	        TagKind::Table(_) => "table (Table)",
535	        TagKind::TR(_) => "table row (TR)",
536	        TagKind::TH(_) => "table header cell (TH)",
537	        TagKind::TD(_) => "table data cell (TD)",
538	        TagKind::THead(_) => "table header (THead)",
539	        TagKind::TBody(_) => "table body (TBody)",
540	        TagKind::TFoot(_) => "table footer (TFoot)",
541	        TagKind::Span(_) => "span (Span)",
542	        TagKind::InlineQuote(_) => "inline quote (Quote)",
543	        TagKind::Note(_) => "note (Note)",
544	        TagKind::Reference(_) => "reference (Reference)",
545	        TagKind::BibEntry(_) => "bibliography entry (BibEntry)",
546	        TagKind::Code(_) => "raw text (Code)",
547	        TagKind::Link(_) => "link (Link)",
548	        TagKind::Annot(_) => "annotation (Annot)",
549	        TagKind::Figure(_) => "figure (Figure)",
550	        TagKind::Formula(_) => "equation (Formula)",
551	        TagKind::Form(_) => "form field (Form)",
552	        TagKind::NonStruct(_) => "non structural element (NonStruct)",
553	        TagKind::Datetime(_) => "date time (Span)",
554	        TagKind::Terms(_) => "terms (P)",
555	        TagKind::Title(_) => "title (Title)",
556	        TagKind::Strong(_) => "strong (Strong/Span)",
557	        TagKind::Em(_) => "emph (Em/Span)",
558	    }
559	}
