1	//! Building the logical tree.
2	//!
3	//! The tree of [`Frame`]s which is split up into pages doesn't necessarily
4	//! represent the logical structure of the Typst document. The logical structure
5	//! is instead defined by the start and end [`introspection::Tag`]s and
6	//! additional insertions of frames by the means of [`Frame::set_parent`].
7	//! These inserted frames resolve to groups of kind [`GroupKind::LogicalChild`].
8	//!
9	//! This module resolves the logical structure in a pre-pass, so that the
10	//! complete logical tree is available when the document's content is converted.
11	//!
12	//! [`introspection::Tag`]: typst_library::introspection::Tag
13	//! [`FrameItem::parent`]: typst_library::layout::FrameItem
14	
15	use std::num::NonZeroU16;
16	use std::ops::ControlFlow;
17	
18	use ecow::EcoVec;
19	use krilla::tagging::{ArtifactType, ListNumbering, Tag, TagKind};
20	use rustc_hash::FxHashMap;
21	use smallvec::SmallVec;
22	use typst_layout::PagedDocument;
23	use typst_library::diag::{
24	    At, ExpectInternal, SourceDiagnostic, SourceResult, assert_internal, bail, error,
25	    panic_internal,
26	};
27	use typst_library::foundations::{Content, ContextElem};
28	use typst_library::introspection::Location;
29	use typst_library::layout::{
30	    Frame, FrameItem, FrameParent, GridCell, GridElem, GroupItem, HideElem, Inherit,
31	    PlaceElem, RepeatElem,
32	};
33	use typst_library::math::EquationElem;
34	use typst_library::model::{
35	    Document, EmphElem, EnumElem, FigureCaption, FigureElem, FootnoteElem, FootnoteEntry,
36	    HeadingElem, LinkMarker, ListElem, Outlinable, OutlineEntry, ParElem, QuoteElem,
37	    StrongElem, TableCell, TableElem, TermsElem, TitleElem,
38	};
39	use typst_library::pdf::{ArtifactElem, PdfMarkerTag, PdfMarkerTagKind};
40	use typst_library::text::{
41	    HighlightElem, OverlineElem, RawElem, RawLine, StrikeElem, SubElem, SuperElem,
42	    UnderlineElem,
43	};
44	use typst_library::visualize::ImageElem;
45	use typst_syntax::Span;
46	
47	use crate::PdfOptions;
48	use crate::tags::GroupId;
49	use crate::tags::context::{Ctx, FigureCtx, GridCtx, ListCtx, OutlineCtx, TableCtx};
50	use crate::tags::groups::{BreakOpportunity, BreakPriority, GroupKind, Groups};
51	use crate::tags::tree::text::TextAttr;
52	use crate::tags::tree::{Break, TraversalStates, Tree, Unfinished};
53	use crate::tags::util::{ArtifactKindExt, PropertyValCopied};
54	use crate::util::ValidatorsExt;
55	
56	pub struct TreeBuilder<'a> {
57	    options: &'a PdfOptions,
58	
59	    /// Each [`FrameItem::Tag`] and each [`FrameItem::Group`] with a parent
60	    /// will append a progression to this tree. This list of progressions is
61	    /// used to determine the location in the tree when doing the actual PDF
62	    /// generation and inserting the marked content sequences.
63	    progressions: Vec<GroupId>,
64	    breaks: Vec<Break>,
65	    unfinished: Vec<Unfinished>,
66	    groups: Groups,
67	    ctx: Ctx,
68	    logical_children: FxHashMap<Location, SmallVec<[GroupId; 4]>>,
69	    errors: EcoVec<SourceDiagnostic>,
70	
71	    stack: TagStack,
72	    /// Currently only used for table/grid cells that are broken across multiple
73	    /// regions, and thus can have opening/closing introspection tags that are
74	    /// in completely different frames, due to the logical parenting mechanism.
75	    unfinished_stacks: FxHashMap<Location, Vec<StackEntry>>,
76	}
77	
78	impl<'a> TreeBuilder<'a> {
79	    pub fn new(document: &PagedDocument, options: &'a PdfOptions) -> Self {
80	        let doc_lang = document.info().locale.custom();
81	        let mut groups = Groups::new();
82	        let doc = groups.new_virtual(
83	            GroupId::INVALID,
84	            Span::detached(),
85	            GroupKind::Root(doc_lang),
86	        );
87	        Self {
88	            options,
89	            progressions: vec![doc],
90	            breaks: Vec::new(),
91	            unfinished: Vec::new(),
92	            groups,
93	            ctx: Ctx::new(),
94	            logical_children: FxHashMap::default(),
95	            errors: EcoVec::new(),
96	
97	            stack: TagStack::new(),
98	            unfinished_stacks: FxHashMap::default(),
99	        }
100	    }
101	
102	    pub fn finish(self) -> Tree {
103	        Tree {
104	            prog_cursor: 0,
105	            progressions: self.progressions,
106	            break_cursor: 0,
107	            breaks: self.breaks,
108	            unfinished_cursor: 0,
109	            unfinished: self.unfinished,
110	            state: TraversalStates::new(),
111	            groups: self.groups,
112	            ctx: self.ctx,
113	            logical_children: self.logical_children,
114	            errors: self.errors,
115	        }
116	    }
117	
118	    pub fn root_document(&self) -> GroupId {
119	        self.progressions[0]
120	    }
121	
122	    /// The last group in the progression.
123	    pub fn current(&self) -> GroupId {
124	        *self.progressions.last().unwrap()
125	    }
126	
127	    /// The last group on the stack or the root document.
128	    pub fn parent(&self) -> GroupId {
129	        self.stack.last().map(|e| e.id).unwrap_or(self.root_document())
130	    }
131	
132	    pub fn parent_kind(&self) -> &GroupKind {
133	        &self.groups.get(self.parent()).kind
134	    }
135	}
136	
137	#[derive(Debug)]
138	struct TagStack {
139	    items: Vec<StackEntry>,
140	}
141	
142	impl std::ops::Deref for TagStack {
143	    type Target = Vec<StackEntry>;
144	
145	    fn deref(&self) -> &Self::Target {
146	        &self.items
147	    }
148	}
149	
150	impl std::ops::DerefMut for TagStack {
151	    fn deref_mut(&mut self) -> &mut Self::Target {
152	        &mut self.items
153	    }
154	}
155	
156	impl TagStack {
157	    fn new() -> Self {
158	        Self { items: Vec::new() }
159	    }
160	
161	    /// Remove all stack entries after the idx.
162	    fn take_unfinished_stack(&mut self, idx: usize) -> Option<Vec<StackEntry>> {
163	        if idx + 1 < self.items.len() {
164	            Some(self.items.drain(idx + 1..).collect())
165	        } else {
166	            None
167	        }
168	    }
169	}
170	
171	#[derive(Debug, Copy, Clone)]
172	struct StackEntry {
173	    /// The location of the stack entry. If this is `None` the stack entry has
174	    /// to be manually popped.
175	    loc: Option<Location>,
176	    id: GroupId,
177	    prog_idx: u32,
178	}
179	
180	pub fn build(document: &PagedDocument, options: &PdfOptions) -> SourceResult<Tree> {
181	    let mut tree = TreeBuilder::new(document, options);
182	    for page in document.pages() {
183	        visit_frame(&mut tree, &page.frame)?;
184	    }
185	
186	    if let Some(last) = tree.stack.last() {
187	        panic_internal("tags weren't properly closed")
188	            .at(tree.groups.get(last.id).span)?;
189	    }
190	    assert_internal(tree.unfinished_stacks.is_empty(), "tags weren't properly closed")
191	        .at(Span::detached())?;
192	    assert_internal(
193	        tree.progressions.first() == tree.progressions.last(),
194	        "tags weren't properly closed",
195	    )
196	    .at(Span::detached())?;
197	
198	    // Insert logical children into the tree.
199	    #[expect(clippy::iter_over_hash_type)]
200	    for (loc, children) in &tree.logical_children {
201	        let located = (tree.groups.by_loc(loc))
202	            .expect_internal("parent group")
203	            .at(Span::detached())?;
204	
205	        if let Some(a11y) = options.standards.config.validators().accessibility()
206	            && located.multiple_parents
207	        {
208	            let validator = a11y.as_str();
209	            let group = tree.groups.get(located.id);
210	            bail!(
211	                group.span,
212	                "{validator} error: ambiguous logical parent";
213	                hint: "please report this as a bug";
214	            );
215	        }
216	
217	        for child in children {
218	            let child = tree.groups.get_mut(*child);
219	
220	            let GroupKind::LogicalChild(inherit, logical_parent) = &mut child.kind else {
221	                unreachable!()
222	            };
223	            *logical_parent = located.id;
224	
225	            // Move the child into its logical parent, so artifact, bbox, and
226	            // text attributes are inherited.
227	            if *inherit == Inherit::Yes {
228	                child.parent = located.id;
229	            }
230	        }
231	    }
232	
233	    #[cfg(debug_assertions)]
234	    for group in tree.groups.list.iter().skip(1) {
235	        assert_ne!(group.parent, GroupId::INVALID);
236	    }
237	
238	    Ok(tree.finish())
239	}
240	
241	fn visit_frame(tree: &mut TreeBuilder, frame: &Frame) -> SourceResult<()> {
242	    for (_, item) in frame.items() {
243	        match item {
244	            FrameItem::Group(group) => visit_group_frame(tree, group)?,
245	            FrameItem::Tag(typst_library::introspection::Tag::Start(elem, flags)) => {
246	                if flags.tagged {
247	                    visit_start_tag(tree, elem);
248	                }
249	            }
250	            FrameItem::Tag(typst_library::introspection::Tag::End(loc, _, flags)) => {
251	                if flags.tagged {
252	                    visit_end_tag(tree, *loc)?;
253	                }
254	            }
255	            FrameItem::Text(_) => (),
256	            FrameItem::Shape(..) => (),
257	            FrameItem::Image(..) => (),
258	            FrameItem::Link(..) => (),
259	        }
260	    }
261	    Ok(())
262	}
263	
264	/// Handle children frames logically belonging to another element, because
265	/// [`typst_library::layout::GroupItem::parent`] has been set. All elements that
266	/// can have children set by this mechanism must be handled in
267	/// [`crate::tags::handle_start`] and must produce a located
268	/// [`crate::tags::groups::Group`], so the children can be inserted there.
269	///
270	/// Currently the frame parent is only set for:
271	/// - place elements [`PlaceElem`]
272	/// - footnote entries [`FootnoteEntry`]
273	/// - broken table/grid cells [`TableCell`]/[`GridCell`]
274	fn visit_group_frame(tree: &mut TreeBuilder, group: &GroupItem) -> SourceResult<()> {
275	    let Some(parent) = group.parent else {
276	        return visit_frame(tree, &group.frame);
277	    };
278	
279	    // Push the logical child.
280	    let prev = tree.current();
281	    let stack_idx = tree.stack.len();
282	    let id = push_logical_child(tree, parent);
283	    tree.progressions.push(id);
284	
285	    // Handle the group frame.
286	    visit_frame(tree, &group.frame)?;
287	
288	    // Pop logical child.
289	    pop_logical_child(tree, parent, stack_idx);
290	    tree.progressions.push(prev);
291	
292	    Ok(())
293	}
294	
295	fn push_logical_child(tree: &mut TreeBuilder, parent: FrameParent) -> GroupId {
296	    let id = tree.groups.new_virtual(
297	        match parent.inherit {
298	            Inherit::Yes => GroupId::INVALID,
299	            Inherit::No => tree.current(),
300	        },
301	        Span::detached(),
302	        GroupKind::LogicalChild(parent.inherit, GroupId::INVALID),
303	    );
304	
305	    tree.logical_children.entry(parent.location).or_default().push(id);
306	
307	    push_stack_entry(tree, None, id);
308	    if let Some(stack) = tree.unfinished_stacks.remove(&parent.location) {
309	        tree.stack.extend(stack);
310	    }
311	    // Move to the top of the stack, including the pushed on unfinished stack.
312	    tree.stack.last().unwrap().id
313	}
314	
315	fn pop_logical_child(tree: &mut TreeBuilder, parent: FrameParent, stack_idx: usize) {
316	    if let Some(stack) = tree.stack.take_unfinished_stack(stack_idx) {
317	        tree.unfinished_stacks.insert(parent.location, stack);
318	        tree.unfinished.push(Unfinished {
319	            prog_idx: tree.progressions.len() as u32,
320	            group_to_close: tree.stack[stack_idx].id,
321	        });
322	    }
323	    tree.stack.pop().expect("stack entry");
324	}
325	
326	fn visit_start_tag(tree: &mut TreeBuilder, elem: &Content) {
327	    let group_id = progress_tree_start(tree, elem);
328	    tree.progressions.push(group_id);
329	}
330	
331	fn visit_end_tag(tree: &mut TreeBuilder, loc: Location) -> SourceResult<()> {
332	    let group = progress_tree_end(tree, loc)?;
333	    tree.progressions.push(group);
334	    Ok(())
335	}
336	
337	fn progress_tree_start(tree: &mut TreeBuilder, elem: &Content) -> GroupId {
338	    // Artifacts
339	    #[expect(clippy::redundant_pattern_matching)]
340	    if let Some(_) = elem.to_packed::<HideElem>() {
341	        push_artifact(tree, elem, ArtifactType::Other)
342	    } else if let Some(artifact) = elem.to_packed::<ArtifactElem>() {
343	        let kind = artifact.kind.val();
344	        push_artifact(tree, elem, kind.to_krilla())
345	    } else if let Some(_) = elem.to_packed::<RepeatElem>() {
346	        push_artifact(tree, elem, ArtifactType::Layout)
347	
348	    // Elements
349	    } else if let Some(tag) = elem.to_packed::<PdfMarkerTag>() {
350	        match &tag.kind {
351	            PdfMarkerTagKind::OutlineBody => {
352	                let id = tree.ctx.outlines.push(OutlineCtx::new());
353	                push_group(tree, elem, GroupKind::Outline(id, None))
354	            }
355	            PdfMarkerTagKind::Bibliography(numbered) => {
356	                let numbering =
357	                    if *numbered { ListNumbering::Decimal } else { ListNumbering::None };
358	                let id = tree.ctx.lists.push(ListCtx::new());
359	                push_group(tree, elem, GroupKind::List(id, numbering, None))
360	            }
361	            PdfMarkerTagKind::BibEntry => {
362	                push_group(tree, elem, GroupKind::BibEntry(None))
363	            }
364	            PdfMarkerTagKind::ListItemLabel => {
365	                push_group(tree, elem, GroupKind::ListItemLabel(None))
366	            }
367	            PdfMarkerTagKind::ListItemBody => {
368	                push_group(tree, elem, GroupKind::ListItemBody(None))
369	            }
370	            PdfMarkerTagKind::TermsItemLabel => {
371	                push_group(tree, elem, GroupKind::TermsItemLabel(None))
372	            }
373	            PdfMarkerTagKind::TermsItemBody => {
374	                push_group(tree, elem, GroupKind::TermsItemBody(None, None))
375	            }
376	            PdfMarkerTagKind::Label => push_tag(tree, elem, Tag::Lbl),
377	        }
378	    } else if let Some(link) = elem.to_packed::<LinkMarker>() {
379	        push_group(tree, elem, GroupKind::Link(link.clone(), None))
380	    } else if let Some(_) = elem.to_packed::<TitleElem>() {
381	        push_tag(tree, elem, Tag::Title)
382	    } else if let Some(entry) = elem.to_packed::<OutlineEntry>() {
383	        push_group(tree, elem, GroupKind::OutlineEntry(entry.clone(), None))
384	    } else if let Some(_) = elem.to_packed::<ListElem>() {
385	        // TODO: infer numbering from `list.marker`
386	        let numbering = ListNumbering::Circle;
387	        let id = tree.ctx.lists.push(ListCtx::new());
388	        push_group(tree, elem, GroupKind::List(id, numbering, None))
389	    } else if let Some(_) = elem.to_packed::<EnumElem>() {
390	        // TODO: infer numbering from `enum.numbering`
391	        let numbering = ListNumbering::Decimal;
392	        let id = tree.ctx.lists.push(ListCtx::new());
393	        push_group(tree, elem, GroupKind::List(id, numbering, None))
394	    } else if let Some(_) = elem.to_packed::<TermsElem>() {
395	        let numbering = ListNumbering::None;
396	        let id = tree.ctx.lists.push(ListCtx::new());
397	        push_group(tree, elem, GroupKind::List(id, numbering, None))
398	    } else if let Some(figure) = elem.to_packed::<FigureElem>() {
399	        let lang = figure.locale;
400	        let bbox = tree.ctx.new_bbox();
401	        let group_id = tree.groups.list.next_id();
402	        let figure_id = tree.ctx.figures.push(FigureCtx::new(group_id, figure.clone()));
403	        push_group(tree, elem, GroupKind::Figure(figure_id, bbox, lang))
404	    } else if let Some(_) = elem.to_packed::<FigureCaption>() {
405	        let bbox = tree.ctx.new_bbox();
406	        push_group(tree, elem, GroupKind::FigureCaption(bbox, None))
407	    } else if let Some(image) = elem.to_packed::<ImageElem>() {
408	        let lang = image.locale;
409	        let bbox = tree.ctx.new_bbox();
410	        push_group(tree, elem, GroupKind::Image(image.clone(), bbox, lang))
411	    } else if let Some(equation) = elem.to_packed::<EquationElem>() {
412	        let lang = equation.locale;
413	        let bbox = tree.ctx.new_bbox();
414	        push_group(tree, elem, GroupKind::Formula(equation.clone(), bbox, lang))
415	    } else if let Some(table) = elem.to_packed::<TableElem>() {
416	        let group_id = tree.groups.list.next_id();
417	        let table_id = tree.ctx.tables.next_id();
418	        tree.ctx.tables.push(TableCtx::new(group_id, table_id, table.clone()));
419	        let bbox = tree.ctx.new_bbox();
420	        push_group(tree, elem, GroupKind::Table(table_id, bbox, None))
421	    } else if let Some(cell) = elem.to_packed::<TableCell>() {
422	        // Only repeated table headers and footer cells are laid out multiple
423	        // times. Mark duplicate headers as artifacts, since they have no
424	        // semantic meaning in the tag tree, which doesn't use page breaks for
425	        // it's semantic structure.
426	        let kind = if cell.is_repeated.val() {
427	            GroupKind::Artifact(ArtifactType::PaginationOther)
428	        } else {
429	            let tag = tree.groups.tags.push(Tag::TD);
430	            GroupKind::TableCell(cell.clone(), tag, None)
431	        };
432	        push_located(tree, elem, kind)
433	    } else if let Some(grid) = elem.to_packed::<GridElem>() {
434	        let group_id = tree.groups.list.next_id();
435	        let id = tree.ctx.grids.push(GridCtx::new(group_id, grid));
436	        push_group(tree, elem, GroupKind::Grid(id, None))
437	    } else if let Some(cell) = elem.to_packed::<GridCell>() {
438	        // The grid cells are collected into a grid to ensure proper reading
439	        // order even when using rowspans, which may be laid out later than
440	        // other cells in the same row.
441	        let kind = if !matches!(tree.parent_kind(), GroupKind::Grid(..)) {
442	            // If there is no grid parent, this means a grid layouter is used
443	            // internally.
444	            GroupKind::Transparent
445	        } else if cell.is_repeated.val() {
446	            // Only repeated grid headers and footer cells are laid out multiple
447	            // times. Mark duplicate headers as artifacts, since they have no
448	            // semantic meaning in the tag tree, which doesn't use page breaks
449	            // for it's semantic structure.
450	            GroupKind::Artifact(ArtifactType::PaginationOther)
451	        } else {
452	            GroupKind::GridCell(cell.clone(), None)
453	        };
454	        push_located(tree, elem, kind)
455	    } else if let Some(heading) = elem.to_packed::<HeadingElem>() {
456	        let level = heading.level().try_into().unwrap_or(NonZeroU16::MAX);
457	        let title = heading.body.plain_text().to_string();
458	        if title.is_empty()
459	            && let Some(accessibility) = tree.options.accessibility_validator()
460	        {
461	            let contains_context = heading.body.traverse(&mut |c| {
462	                if c.is::<ContextElem>() {
463	                    return ControlFlow::Break(());
464	                }
465	                ControlFlow::Continue(())
466	            });
467	            let validator = accessibility.as_str();
468	            tree.errors.push(if contains_context.is_break() {
469	                error!(
470	                    heading.span(),
471	                    "{validator} error: heading title could not be determined";
472	                    hint: "this seems to be caused by a context expression within the \
473	                           heading";
474	                    hint: "consider wrapping the entire heading in a context expression \
475	                           instead";
476	                )
477	            } else {
478	                error!(heading.span(), "{validator} error: heading title is empty")
479	            });
480	        }
481	        push_tag(tree, elem, Tag::Hn(level, Some(title)))
482	    } else if let Some(_) = elem.to_packed::<FootnoteElem>() {
483	        push_located(tree, elem, GroupKind::LogicalParent(elem.clone()))
484	    } else if let Some(_) = elem.to_packed::<FootnoteEntry>() {
485	        push_tag(tree, elem, Tag::Note)
486	    } else if let Some(quote) = elem.to_packed::<QuoteElem>() {
487	        // TODO: should the attribution be handled somehow?
488	        if quote.block.val() {
489	            push_tag(tree, elem, Tag::BlockQuote)
490	        } else {
491	            push_tag(tree, elem, Tag::InlineQuote)
492	        }
493	    } else if let Some(raw) = elem.to_packed::<RawElem>() {
494	        if raw.block.val() {
495	            push_group(tree, elem, GroupKind::CodeBlock(None))
496	        } else {
497	            push_tag(tree, elem, Tag::Code)
498	        }
499	    } else if let Some(_) = elem.to_packed::<RawLine>() {
500	        // If the raw element is inline, the content can be inserted directly.
501	        if matches!(tree.parent_kind(), GroupKind::CodeBlock(..)) {
502	            push_group(tree, elem, GroupKind::CodeBlockLine(None))
503	        } else {
504	            no_progress(tree)
505	        }
506	    } else if let Some(place) = elem.to_packed::<PlaceElem>() {
507	        if place.float.val() {
508	            push_located(tree, elem, GroupKind::LogicalParent(elem.clone()))
509	        } else {
510	            no_progress(tree)
511	        }
512	    } else if let Some(_) = elem.to_packed::<ParElem>() {
513	        push_weak(tree, elem, GroupKind::Par(None))
514	
515	    // Text attributes
516	    } else if let Some(_strong) = elem.to_packed::<StrongElem>() {
517	        push_text_attr(tree, elem, TextAttr::Strong)
518	    } else if let Some(_emph) = elem.to_packed::<EmphElem>() {
519	        push_text_attr(tree, elem, TextAttr::Emph)
520	    } else if let Some(sub) = elem.to_packed::<SubElem>() {
521	        push_text_attr(tree, elem, TextAttr::SubScript(sub.clone()))
522	    } else if let Some(sup) = elem.to_packed::<SuperElem>() {
523	        push_text_attr(tree, elem, TextAttr::SuperScript(sup.clone()))
524	    } else if let Some(highlight) = elem.to_packed::<HighlightElem>() {
525	        push_text_attr(tree, elem, TextAttr::Highlight(highlight.clone()))
526	    } else if let Some(underline) = elem.to_packed::<UnderlineElem>() {
527	        push_text_attr(tree, elem, TextAttr::Underline(underline.clone()))
528	    } else if let Some(overline) = elem.to_packed::<OverlineElem>() {
529	        push_text_attr(tree, elem, TextAttr::Overline(overline.clone()))
530	    } else if let Some(strike) = elem.to_packed::<StrikeElem>() {
531	        push_text_attr(tree, elem, TextAttr::Strike(strike.clone()))
532	    } else {
533	        no_progress(tree)
534	    }
535	}
536	
537	fn no_progress(tree: &TreeBuilder) -> GroupId {
538	    tree.current()
539	}
540	
541	fn push_tag(tree: &mut TreeBuilder, elem: &Content, tag: impl Into<TagKind>) -> GroupId {
542	    let id = tree.groups.tags.push(tag.into());
543	    push_group(tree, elem, GroupKind::Standard(id, None))
544	}
545	
546	fn push_text_attr(tree: &mut TreeBuilder, elem: &Content, attr: TextAttr) -> GroupId {
547	    push_group(tree, elem, GroupKind::TextAttr(attr))
548	}
549	
550	fn push_artifact(tree: &mut TreeBuilder, elem: &Content, ty: ArtifactType) -> GroupId {
551	    push_group(tree, elem, GroupKind::Artifact(ty))
552	}
553	
554	fn push_group(tree: &mut TreeBuilder, elem: &Content, kind: GroupKind) -> GroupId {
555	    let loc = elem.location().expect("elem to have a location");
556	    let span = elem.span();
557	    let parent = tree.current();
558	    let id = tree.groups.new_virtual(parent, span, kind);
559	    push_stack_entry(tree, Some(loc), id)
560	}
561	
562	fn push_located(tree: &mut TreeBuilder, elem: &Content, kind: GroupKind) -> GroupId {
563	    let loc = elem.location().expect("elem to have a location");
564	    let span = elem.span();
565	    let parent = tree.current();
566	    let id = tree.groups.new_located(loc, parent, span, kind);
567	    push_stack_entry(tree, Some(loc), id)
568	}
569	
570	fn push_weak(tree: &mut TreeBuilder, elem: &Content, kind: GroupKind) -> GroupId {
571	    let loc = elem.location().expect("elem to have a location");
572	    let span = elem.span();
573	    let parent = tree.current();
574	    let id = tree.groups.new_weak(parent, span, kind);
575	    push_stack_entry(tree, Some(loc), id)
576	}
577	
578	fn push_stack_entry(
579	    tree: &mut TreeBuilder,
580	    loc: Option<Location>,
581	    id: GroupId,
582	) -> GroupId {
583	    let prog_idx = tree.progressions.len() as u32;
584	    let entry = StackEntry { loc, id, prog_idx };
585	    tree.stack.push(entry);
586	    id
587	}
588	
589	fn progress_tree_end(tree: &mut TreeBuilder, loc: Location) -> SourceResult<GroupId> {
590	    if tree.stack.pop_if(|e| e.loc == Some(loc)).is_some() {
591	        // The tag nesting was properly closed.
592	        return Ok(tree.parent());
593	    }
594	
595	    // Search for an improperly nested starting tag, that is being closed.
596	    let Some(stack_idx) = (tree.stack.iter().enumerate())
597	        .rev()
598	        .find_map(|(i, e)| (e.loc == Some(loc)).then_some(i))
599	    else {
600	        // The start tag isn't in the tag stack, just ignore the end tag.
601	        return Ok(no_progress(tree));
602	    };
603	
604	    let entry = tree.stack[stack_idx];
605	    let outer = tree.groups.get(entry.id);
606	
607	    // There are overlapping tags in the tag tree. Figure out whether breaking
608	    // up the current tag stack is semantically ok, and how to do it.
609	    let is_pdf_ua = tree.options.accessibility_validator().is_some();
610	    let mut inner_break_priority = Some(BreakPriority::MAX);
611	    let mut inner_non_breakable_span = Span::detached();
612	    let mut inner_non_breakable_in_pdf_ua = false;
613	    for e in tree.stack.iter().skip(stack_idx + 1) {
614	        let group = tree.groups.get(e.id);
615	        let opportunity = tree.groups.breakable(&group.kind);
616	        let Some(priority) = opportunity.get(is_pdf_ua) else {
617	            if inner_non_breakable_span.is_detached() {
618	                inner_non_breakable_span = group.span;
619	            }
620	            if let BreakOpportunity::NoPdfUa(_) = opportunity {
621	                inner_non_breakable_in_pdf_ua = true;
622	            }
623	            inner_break_priority = None;
624	            continue;
625	        };
626	
627	        if let Some(inner) = &mut inner_break_priority {
628	            *inner = (*inner).min(priority);
629	        }
630	    }
631	
632	    let outer_break_opportunity = tree.groups.breakable(&outer.kind);
633	    let outer_break_priority = outer_break_opportunity.get(is_pdf_ua);
634	
635	    match (outer_break_priority, inner_break_priority) {
636	        (Some(outer_priority), Some(inner_priority)) => {
637	            // Prefer splitting up the inner groups.
638	            if inner_priority >= outer_priority {
639	                Ok(split_inner_groups(tree, outer.parent, stack_idx))
640	            } else {
641	                Ok(split_outer_group(tree, outer.parent, stack_idx))
642	            }
643	        }
644	        (Some(_), None) => Ok(split_outer_group(tree, outer.parent, stack_idx)),
645	        (None, Some(_)) => Ok(split_inner_groups(tree, outer.parent, stack_idx)),
646	        (None, None) => {
647	            let non_breakable_span = inner_non_breakable_span.or(outer.span);
648	
649	            let non_breakable_in_pdf_ua = inner_non_breakable_in_pdf_ua
650	                || matches!(outer_break_opportunity, BreakOpportunity::NoPdfUa(_));
651	
652	            if non_breakable_in_pdf_ua {
653	                let validator =
654	                    tree.options.standards.config.validators().to_comma_list();
655	                bail!(
656	                    non_breakable_span,
657	                    "{validator} error: invalid document structure, \
658	                     this element's PDF tag would be split up";
659	                    hint: "this is probably caused by paragraph grouping";
660	                    hint: "maybe you've used a `parbreak`, `colbreak`, or `pagebreak`";
661	                );
662	            } else {
663	                bail!(
664	                    non_breakable_span,
665	                    "invalid document structure, \
666	                     this element's PDF tag would be split up";
667	                    hint: "please report this as a bug";
668	                );
669	            }
670	        }
671	    }
672	}
673	
674	/// Consider the following introspection tags:
675	/// ```txt
676	/// start a
677	///   start b
678	///     start c
679	/// end   a
680	///     end   c
681	///   end   b
682	/// ```
683	/// This will split the inner groups, producing the following tag tree:
684	/// ```yml
685	/// - a:
686	///   - b:
687	///     - c:
688	/// - b:
689	///   - c:
690	/// ```
691	fn split_inner_groups(
692	    tree: &mut TreeBuilder,
693	    mut parent: GroupId,
694	    stack_idx: usize,
695	) -> GroupId {
696	    // Since the broken groups won't be visited again in any future progression,
697	    // they'll need to be closed when this progression is visited.
698	    let num_closed = (tree.stack.len() - stack_idx) as u16;
699	    tree.breaks.push(Break {
700	        prog_idx: tree.progressions.len() as u32,
701	        num_closed,
702	        num_opened: num_closed - 1,
703	    });
704	
705	    // Remove the closed entry.
706	    tree.stack.remove(stack_idx);
707	
708	    // Duplicate all broken entries.
709	    for entry in tree.stack.iter_mut().skip(stack_idx) {
710	        let new_id = tree.groups.break_group(entry.id, parent);
711	        *entry = StackEntry {
712	            loc: entry.loc,
713	            id: new_id,
714	            prog_idx: tree.progressions.len() as u32,
715	        };
716	        parent = new_id;
717	    }
718	
719	    // We're now in a new duplicated group
720	    tree.parent()
721	}
722	
723	/// Consider the following introspection tags:
724	/// ```txt
725	/// OPEN a
726	///   OPEN b
727	///     OPEN c
728	/// END  a
729	///     END  c
730	///   END  b
731	/// ```
732	/// This will split the outer group, producing the following tag tree:
733	/// ```yml
734	/// - a:
735	/// - b:
736	///   - a:
737	///   - c:
738	///     - a:
739	/// ```
740	fn split_outer_group(
741	    tree: &mut TreeBuilder,
742	    parent: GroupId,
743	    stack_idx: usize,
744	) -> GroupId {
745	    let prev = tree.current();
746	
747	    // Remove the closed entry;
748	    let outer = tree.stack.remove(stack_idx);
749	
750	    // Move the nested group out of the outer entry.
751	    tree.groups.get_mut(tree.stack[stack_idx].id).parent = parent;
752	
753	    let mut entry_iter = tree.stack.iter().skip(stack_idx).peekable();
754	    while let Some(entry) = entry_iter.next() {
755	        let next_entry = entry_iter.peek().map(|e| e.id);
756	
757	        let nested = tree.groups.break_group(outer.id, entry.id);
758	
759	        // Move all children of the stack entry into the nested group.
760	        for (id, group) in tree.groups.list.ids().zip(tree.groups.list.iter_mut()).rev() {
761	            // Avoid searching *all* groups! The children of this group are guaranteed to be
762	            // created after the outer group and thus have a higher ID.
763	            if id == outer.id {
764	                break;
765	            }
766	
767	            // Don't move the nested group into itself, or the next stack entry
768	            // into the nested group.
769	            if group.parent == entry.id && id != nested && Some(id) != next_entry {
770	                group.parent = nested;
771	            }
772	        }
773	
774	        // Update progressions to jump into the inner entry instead.
775	        let prev = tree.progressions[entry.prog_idx as usize];
776	        for prog in &mut tree.progressions[entry.prog_idx as usize..] {
777	            if *prog == prev {
778	                *prog = nested;
779	            }
780	        }
781	
782	        // Either update an existing break, or insert a new one.
783	        let mut break_idx = Some(tree.breaks.len());
784	        for (i, brk) in tree.breaks.iter_mut().enumerate().rev() {
785	            if brk.prog_idx == entry.prog_idx {
786	                brk.num_closed += 1;
787	                brk.num_opened += 1;
788	                break_idx = None;
789	                break;
790	            } else if brk.prog_idx < entry.prog_idx {
791	                break_idx = Some(i + 1);
792	                break;
793	            }
794	        }
795	        if let Some(idx) = break_idx {
796	            // Insert a break to close the previous broken group, and enter
797	            // the new group.
798	            let brk = Break {
799	                prog_idx: entry.prog_idx,
800	                num_closed: 1,
801	                num_opened: 2,
802	            };
803	            tree.breaks.insert(idx, brk);
804	        }
805	    }
806	
807	    // We're still in the same group, but the outer group has been split up.
808	    debug_assert_eq!(tree.parent(), prev);
809	
810	    tree.parent()
811	}
812

