58	    pub fn new(group_id: GroupId, table_id: TableId, table: Packed<TableElem>) -> Self {
59	        let grid = table.grid.as_ref().unwrap();
60	        let width = grid.non_gutter_column_count();
61	        let height = grid.non_gutter_row_count();
62	
63	        // Generate the default row kinds.
64	        let mut grid_headers = grid.headers.iter().peekable();
65	        let default_row_kinds = (0..height as u32)
66	            .map(|y| {
67	                let grid_y = grid.to_effective(y);
68	
69	                // Find current header
70	                while grid_headers.next_if(|h| h.range.end <= grid_y).is_some() {}
71	                if let Some(header) = grid_headers.peek()
72	                    && header.range.contains(&grid_y)
73	                {
74	                    return TableCellKind::Header(header.level, TableHeaderScope::Column);
75	                }
76	
77	                if let Some(footer) = &grid.footer
78	                    && footer.range().contains(&grid_y)
79	                {
80	                    return TableCellKind::Footer;
81	                }
82	
83	                TableCellKind::Data
84	            })
85	            .collect::<Vec<_>>();
86	
87	        Self {
88	            group_id,
89	            table_id,
90	            elem: table,
91	            row_kinds: default_row_kinds,
92	            cells: GridCells::new(width, height),
93	            border_thickness: None,
94	            border_color: None,
95	        }
96	    }
97	
98	    pub fn insert(&mut self, cell: &Packed<TableCell>, tag: TagId, id: GroupId) {
99	        let x = cell.x.val().unwrap_or_else(|| unreachable!()).saturating_as();
100	        let y = cell.y.val().unwrap_or_else(|| unreachable!()).saturating_as();
101	        let rowspan = cell.rowspan.val();
102	        let colspan = cell.colspan.val();
103	        let grid = self.elem.grid.as_deref().unwrap();
104	
105	        let kind = cell.kind.val().unwrap_or(self.row_kinds[y as usize]);
106	
107	        let [grid_x, grid_y] = [x, y].map(|i| grid.to_effective(i));
108	        let grid_cell = grid.cell(grid_x, grid_y).unwrap();
109	        let stroke = grid_cell.stroke.clone().zip(grid_cell.stroke_overridden).map(
110	            |(stroke, overridden)| {
111	                let priority = if overridden {
112	                    StrokePriority::CellStroke
113	                } else {
114	                    StrokePriority::GridStroke
115	                };
116	                PrioritzedStroke { stroke, priority }
117	            },
118	        );
119	        self.cells.insert(CtxCell {
120	            data: TableCellData { tag, kind, headers: SmallVec::new(), stroke },
121	            x,
122	            y,
123	            rowspan: rowspan.try_into().unwrap_or(NonZeroU32::MAX),
124	            colspan: colspan.try_into().unwrap_or(NonZeroU32::MAX),
125	            id,
126	        });
127	    }
128	
129	    pub fn build_tag(&self) -> TagKind {
130	        Tag::Table
131	            .with_summary(self.elem.summary.opt_ref().map(Into::into))
132	            .with_border_thickness(self.border_thickness.map(kt::Sides::uniform))
133	            .with_border_color(self.border_color.map(kt::Sides::uniform))
134	            .into()
135	    }
136	}
137	
138	pub fn build_table(tree: &mut Tree, table_id: TableId) {
139	    let table_ctx = tree.ctx.tables.get_mut(table_id);
140	
141	    // Table layouting ensures that there are no overlapping cells, and that
142	    // any gaps left by the user are filled with empty cells.
143	    // A show rule, can prevent the table from being properly laid out, in which
144	    // case cells will be missing.
145	    if table_ctx.cells.is_empty() || table_ctx.cells.iter().any(GridEntry::is_missing) {
146	        // Insert all children, so the content is included in the tag tree,
147	        // otherwise krilla might panic.
148	        for cell in table_ctx.cells.iter().filter_map(GridEntry::as_cell) {
149	            tree.groups.push_group(table_ctx.group_id, cell.id);
150	        }
151	
152	        return;
153	    }
154	
155	    let width = table_ctx.cells.width();
156	    let height = table_ctx.cells.height();
157	    let grid = table_ctx.elem.grid.as_deref().unwrap();
158	
159	    // Only generate row groups such as `THead`, `TFoot`, and `TBody` if
160	    // there are no rows with mixed cell kinds, and there is at least one
161	    // header or a footer.
162	    let gen_row_groups = {
163	        let mut uniform_rows = true;
164	        let mut has_header_or_footer = false;
165	        let mut has_body = false;
166	        'outer: for (row, row_kind) in
167	            table_ctx.cells.rows().zip(table_ctx.row_kinds.iter_mut())
168	        {
169	            let first_cell = table_ctx.cells.resolve(row.first().unwrap()).unwrap();
170	            let first_kind = first_cell.data.kind;
171	
172	            for cell in row.iter().filter_map(|cell| table_ctx.cells.resolve(cell)) {
173	                if let TableCellKind::Header(_, scope) = cell.data.kind
174	                    && scope != TableHeaderScope::Column
175	                {
176	                    uniform_rows = false;
177	                    break 'outer;
178	                }
179	
180	                if first_kind != cell.data.kind {
181	                    uniform_rows = false;
182	                    break 'outer;
183	                }
184	            }
185	
186	            // If all cells in the row have the same custom kind, the row
187	            // kind is overwritten.
188	            *row_kind = first_kind;
189	
190	            has_header_or_footer |= *row_kind != TableCellKind::Data;
191	            has_body |= *row_kind == TableCellKind::Data;
192	        }
193	
194	        uniform_rows && has_header_or_footer && has_body
195	    };
196	
197	    // Compute the headers attribute column-wise.
198	    for x in 0..width {
199	        let mut column_headers = Vec::new();
200	        let mut grid_headers = grid.headers.iter().peekable();
201	        for y in 0..height {
202	            // Find current header region
203	            let grid_y = grid.to_effective(y);
204	            while grid_headers.next_if(|h| h.range.end <= grid_y).is_some() {}
205	            let region_range = grid_headers.peek().and_then(|header| {
206	                if !header.range.contains(&grid_y) {
207	                    return None;
208	                }
209	
210	                // Convert from the `CellGrid` coordinates to normal ones.
211	                let start = grid.from_effective(header.range.start);
212	                let end = grid.from_effective(header.range.end);
213	                Some(start..end)
214	            });
215	
216	            resolve_cell_headers(
217	                table_ctx.table_id,
218	                &mut table_ctx.cells,
219	                &mut column_headers,
220	                region_range,
221	                TableHeaderScope::refers_to_column,
222	                (x, y),
223	            );
224	        }
225	    }
226	    // Compute the headers attribute row-wise.
227	    for y in 0..height {
228	        let mut row_headers = Vec::new();
229	        for x in 0..width {
230	            resolve_cell_headers(
231	                table_ctx.table_id,
232	                &mut table_ctx.cells,
233	                &mut row_headers,
234	                None,
235	                TableHeaderScope::refers_to_row,
236	                (x, y),
237	            );
238	        }
239	    }
240	
241	    // Place h-lines, overwriting the cells stroke.
242	    place_explicit_lines(
243	        &mut table_ctx.cells,
244	        &grid.hlines,
245	        height,
246	        width,
247	        |cells, (y, x), pos| {
248	            let cell = cells.cell_mut(x, y)?;
249	            Some(match pos {
250	                LinePosition::Before => &mut cell.data.stroke.bottom,
251	                LinePosition::After => &mut cell.data.stroke.top,
252	            })
253	        },
254	    );
255	    // Place v-lines, overwriting the cells stroke.
256	    place_explicit_lines(
257	        &mut table_ctx.cells,
258	        &grid.vlines,
259	        width,
260	        height,
261	        |cells, (x, y), pos| {
262	            let cell = cells.cell_mut(x, y)?;
263	            Some(match pos {
264	                LinePosition::Before => &mut cell.data.stroke.right,
265	                LinePosition::After => &mut cell.data.stroke.left,
266	            })
267	        },
268	    );
269	
270	    // Remove overlapping border strokes between cells.
271	    for y in 0..height {
272	        for x in 0..width.saturating_sub(1) {
273	            prioritize_strokes(&mut table_ctx.cells, (x, y), (x + 1, y), |a, b| {
274	                (&mut a.stroke.right, &mut b.stroke.left)
275	            });
276	        }
277	    }
278	    for x in 0..width {
279	        for y in 0..height.saturating_sub(1) {
280	            prioritize_strokes(&mut table_ctx.cells, (x, y), (x, y + 1), |a, b| {
281	                (&mut a.stroke.bottom, &mut b.stroke.top)
282	            });
283	        }
284	    }
285	
286	    (table_ctx.border_thickness, table_ctx.border_color) =
287	        try_resolve_table_stroke(&table_ctx.cells);
288	
289	    let mut chunk_kind = table_ctx.row_kinds[0];
290	    let mut chunk_id = GroupId::INVALID;
291	    for (row, y) in table_ctx.cells.rows_mut().zip(0..) {
292	        let parent = if gen_row_groups {
293	            let row_kind = table_ctx.row_kinds[y as usize];
294	            let is_first = chunk_id == GroupId::INVALID;
295	            if is_first || !should_group_rows(chunk_kind, row_kind) {
296	                let tag: TagKind = match row_kind {
297	                    // Only one `THead` group at the start of the table is permitted.
298	                    TableCellKind::Header(..) if is_first => Tag::THead.into(),
299	                    TableCellKind::Header(..) => Tag::TBody.into(),
300	                    TableCellKind::Footer => Tag::TFoot.into(),
301	                    TableCellKind::Data => Tag::TBody.into(),
302	                };
303	                chunk_kind = row_kind;
304	                chunk_id = tree.groups.push_tag(table_ctx.group_id, tag);
305	            }
306	            chunk_id
307	        } else {
308	            table_ctx.group_id
309	        };
310	
311	        let row_id = tree.groups.push_tag(parent, Tag::TR);
312	        let row_nodes = row
313	            .iter_mut()
314	            .filter_map(|entry| {
315	                let cell = entry.as_cell_mut()?;
316	                let rowspan = (cell.rowspan.get() != 1).then_some(cell.rowspan);
317	                let colspan = (cell.colspan.get() != 1).then_some(cell.colspan);
318	                let cell_kind = cell.data.kind;
319	                let headers = std::mem::take(&mut cell.data.headers);
320	                let mut tag: TagKind = match cell_kind {
321	                    TableCellKind::Header(_, scope) => {
322	                        let id = table_cell_id(table_ctx.table_id, cell.x, cell.y);
323	                        Tag::TH(scope.to_krilla())
324	                            .with_id(Some(id))
325	                            .with_headers(Some(headers))
326	                            .with_row_span(rowspan)
327	                            .with_col_span(colspan)
328	                            .into()
329	                    }
330	                    TableCellKind::Footer | TableCellKind::Data => Tag::TD
331	                        .with_headers(Some(headers))
332	                        .with_row_span(rowspan)
333	                        .with_col_span(colspan)
334	                        .into(),
335	                };
336	
337	                resolve_cell_border_and_background(
338	                    grid,
339	                    table_ctx.border_thickness,
340	                    table_ctx.border_color,
341	                    [cell.x, cell.y],
342	                    &cell.data.stroke,
343	                    &mut tag,
344	                );
345	
346	                tree.groups.tags.set(cell.data.tag, tag);
347	
348	                Some(cell.id)
349	            })
350	            .collect::<Vec<_>>();
351	
352	        tree.groups.push_groups(row_id, &row_nodes);
353	    }
354	}
355	
356	fn should_group_rows(a: TableCellKind, b: TableCellKind) -> bool {
357	    match (a, b) {
358	        (TableCellKind::Header(..), TableCellKind::Header(..)) => true,
359	        (TableCellKind::Footer, TableCellKind::Footer) => true,
360	        (TableCellKind::Data, TableCellKind::Data) => true,
361	        (_, _) => false,
362	    }
363	}
364	
365	struct HeaderCells {
366	    /// If this header is inside a table header regions defined by a
367	    /// `table.header()` call, this is the range of that region.
368	    /// Currently this is only supported for multi row headers.
369	    region_range: Option<Range<u32>>,
370	    level: NonZeroU32,
371	    cell_ids: SmallVec<[kt::TagId; 1]>,
372	}
373	
374	fn resolve_cell_headers<F>(
375	    table_id: TableId,
376	    cells: &mut GridCells<TableCellData>,
377	    header_stack: &mut Vec<HeaderCells>,
378	    region_range: Option<Range<u32>>,
379	    refers_to_dir: F,
380	    (x, y): (u32, u32),
381	) where
382	    F: Fn(&TableHeaderScope) -> bool,
383	{
384	    let Some(cell) = cells.cell_mut(x, y) else { return };
385	
386	    let cell_ids = resolve_cell_header_ids(
387	        table_id,
388	        header_stack,
389	        region_range,
390	        refers_to_dir,
391	        cell,
392	    );
393	
394	    if let Some(header) = cell_ids {
395	        for id in &header.cell_ids {
396	            if !cell.data.headers.contains(id) {
397	                cell.data.headers.push(id.clone());
398	            }
399	        }
400	    }
401	}
402	
403	fn resolve_cell_header_ids<'a, F>(
404	    table_id: TableId,
405	    header_stack: &'a mut Vec<HeaderCells>,
406	    region_range: Option<Range<u32>>,
407	    refers_to_dir: F,
408	    cell: &CtxCell<TableCellData>,
409	) -> Option<&'a HeaderCells>
410	where
411	    F: Fn(&TableHeaderScope) -> bool,
412	{
413	    let TableCellKind::Header(level, scope) = cell.data.kind else {
414	        return header_stack.last();
415	    };
416	    if !refers_to_dir(&scope) {
417	        return header_stack.last();
418	    }
419	
420	    // Remove all headers with a higher level.
421	    while header_stack.pop_if(|h| h.level > level).is_some() {}
422	
423	    let tag_id = table_cell_id(table_id, cell.x, cell.y);
424	
425	    // Check for multi-row header regions with the same level.
426	    let Some(prev) = header_stack.last_mut().filter(|h| h.level == level) else {
427	        header_stack.push(HeaderCells {
428	            region_range,
429	            level,
430	            cell_ids: SmallVec::from_buf([tag_id]),
431	        });
432	        return header_stack.iter().rev().nth(1);
433	    };
434	
435	    // If the current header region encompasses the cell, add the cell id to
436	    // the header. This way multiple consecutive header cells in a single header
437	    // region will be listed for the next cells.
438	    if prev.region_range.clone().is_some_and(|r| r.contains(&cell.y)) {
439	        prev.cell_ids.push(tag_id);
440	    } else {
441	        // The current region doesn't encompass the cell.
442	        // Replace the previous heading that had the same level.
443	        *prev = HeaderCells {
444	            region_range,
445	            level,
446	            cell_ids: SmallVec::from_buf([tag_id]),
447	        };
448	    }
449	
450	    header_stack.iter().rev().nth(1)
451	}
452	
453	fn table_cell_id(table_id: TableId, x: u32, y: u32) -> kt::TagId {
454	    // 32 bytes is the maximum length the ID string can have.
455	    let mut buf = SmallVec::<[u8; 32]>::new();
456	    _ = write!(&mut buf, "{}x{x}y{y}", table_id.get() + 1);
457	    kt::TagId::from(buf)
458	}
459	
460	fn place_explicit_lines<F>(
461	    cells: &mut GridCells<TableCellData>,
462	    lines: &[Vec<Line>],
463	    block_end: u32,
464	    inline_end: u32,
465	    get_side: F,
466	) where
467	    F: Fn(
468	        &mut GridCells<TableCellData>,
469	        (u32, u32),
470	        LinePosition,
471	    ) -> Option<&mut PrioritzedStroke>,
472	{
473	    for line in lines.iter().flat_map(|lines| lines.iter()) {
474	        let end = line.end.map(|n| n.get() as u32).unwrap_or(inline_end).min(inline_end);
475	        let explicit_stroke = || PrioritzedStroke {
476	            stroke: line.stroke.clone(),
477	            priority: StrokePriority::ExplicitLine,
478	        };
479	
480	        // Fixup line positions before the first, or after the last cell.
481	        let mut pos = line.position;
482	        if line.index == 0 {
483	            pos = LinePosition::After;
484	        } else if line.index + 1 == block_end as usize {
485	            pos = LinePosition::Before;
486	        }
487	
488	        let block_idx = match pos {
489	            LinePosition::Before => (line.index - 1) as u32,
490	            LinePosition::After => line.index as u32,
491	        };
492	        for inline_idx in line.start as u32..end {
493	            if let Some(side) = get_side(cells, (block_idx, inline_idx), pos) {
494	                *side = explicit_stroke();
495	            }
496	        }
497	    }
498	}
499	
500	/// PDF tables don't support gutters, remove all overlapping strokes,
501	/// that aren't equal. Leave strokes that would overlap but are the same
502	/// because then only a single value has to be written for `BorderStyle`,
503	/// `BorderThickness`, and `BorderColor` instead of an array for each.
504	fn prioritize_strokes<F>(
505	    cells: &mut GridCells<TableCellData>,
506	    a: (u32, u32),
507	    b: (u32, u32),
508	    get_sides: F,
509	) where
510	    F: for<'a> Fn(
511	        &'a mut TableCellData,
512	        &'a mut TableCellData,
513	    ) -> (&'a mut PrioritzedStroke, &'a mut PrioritzedStroke),
514	{
515	    let Some([a, b]) = cells.cells_disjoint_mut([a, b]) else { return };
516	
517	    let (a, b) = get_sides(&mut a.data, &mut b.data);
518	
519	    // Only remove contesting (different) edge strokes.
520	    if a.stroke != b.stroke {
521	        // Prefer the right stroke on same priorities.
522	        if a.priority <= b.priority {
523	            a.stroke = b.stroke.clone();
524	        } else {
525	            b.stroke = a.stroke.clone();
526	        }
527	    }
528	}
529	
530	/// Try to resolve a table border stroke color and thickness that is inherited
531	/// by the cells. In Acrobat cells cannot override the border thickness or color
532	/// of the outer border around the table if the thickness is set.
533	fn try_resolve_table_stroke(
534	    cells: &GridCells<TableCellData>,
535	) -> (Option<f32>, Option<NaiveRgbColor>) {
536	    // Omitted strokes are counted too for reasons explained above.
537	    let mut strokes = FxHashMap::<_, usize>::default();
538	    for cell in cells.iter().filter_map(GridEntry::as_cell) {
539	        for stroke in cell.data.stroke.iter() {
540	            *strokes.entry(stroke.stroke.as_ref()).or_default() += 1;
541	        }
542	    }
543	
544	    let uniform_stroke = strokes.len() == 1;
545	
546	    // Find the most used stroke and convert it to a fixed stroke.
547	    let stroke = strokes.into_iter().max_by_key(|(_, num)| *num).and_then(|(s, _)| {
548	        let s = (**s?).clone();
549	        Some(s.unwrap_or_default())
550	    });
551	    let Some(stroke) = stroke else { return (None, None) };
552	
553	    // Only set a parent stroke width if the table uses one uniform stroke.
554	    let thickness = uniform_stroke.then_some(stroke.thickness.to_f32());
555	    let color = util::paint_to_color(&stroke.paint);
556	
557	    (thickness, color)
558	}
559	
560	fn resolve_cell_border_and_background(
561	    grid: &CellGrid,
562	    parent_border_thickness: Option<f32>,
563	    parent_border_color: Option<NaiveRgbColor>,
564	    pos: [u32; 2],
565	    stroke: &Sides<PrioritzedStroke>,
566	    tag: &mut TagKind,
567	) {
568	    // Resolve border attributes.
569	    let fixed = stroke
570	        .as_ref()
571	        .map(|s| s.stroke.as_ref().map(|s| (**s).clone().unwrap_or_default()));
572	
573	    // Acrobat completely ignores the border style attribute, but the spec
574	    // defines `BorderStyle::None` as the default. So make sure to write
575	    // the correct border styles.
576	    let border_style = resolve_sides(&fixed, None, Some(kt::BorderStyle::None), |s| {
577	        Some(match s.dash {
578	            Some(_) => kt::BorderStyle::Dashed,
579	            None => kt::BorderStyle::Solid,
580	        })
581	    });
582	
583	    // In Acrobat `BorderThickness` takes precedence over `BorderStyle`. If
584	    // A `BorderThickness != 0` is specified for a side the border is drawn
585	    // even if `BorderStyle::None` is set. So explicitly write zeros for
586	    // sides that should be omitted.
587	    let border_thickness =
588	        resolve_sides(&fixed, parent_border_thickness, Some(0.0), |s| {
589	            Some(s.thickness.to_f32())
590	        });
591	
592	    let border_color = resolve_sides(&fixed, parent_border_color, None, |s| {
593	        util::paint_to_color(&s.paint)
594	    });
595	
596	    tag.set_border_style(border_style);
597	    tag.set_border_thickness(border_thickness);
598	    tag.set_border_color(border_color);
599	
600	    let [grid_x, grid_y] = pos.map(|i| grid.to_effective(i));
601	    let grid_cell = grid.cell(grid_x, grid_y).unwrap();
602	    let background_color = grid_cell.fill.as_ref().and_then(util::paint_to_color);
603	    tag.set_background_color(background_color);
604	}
605	
606	/// Try to minimize the attributes written per cell.
607	/// The parent value will be set on the table tag and is inherited by all table
608	/// cells. If all present values match the parent or all are missing, the
609	/// attribute can be omitted, and thus `None` is returned.
610	/// If one of the present values differs from the parent value, the cell
611	/// attribute needs to override the parent attribute, fill up the remaining
612	/// sides with a `default` value if provided, or any other present value.
613	///
614	/// Using an already present value has the benefit of saving storage space in
615	/// the resulting PDF, if all sides have the same value, because then a
616	/// [`kt::Sides::uniform`] value can be written instead of a 4-element array.
617	fn resolve_sides<F, T>(
618	    sides: &Sides<Option<FixedStroke>>,
619	    parent: Option<T>,
620	    default: Option<T>,
621	    map_stroke: F,
622	) -> Option<kt::Sides<T>>
623	where
624	    T: Copy + PartialEq,
625	    F: Copy + Fn(&FixedStroke) -> Option<T>,
626	{
627	    let mapped = sides.as_ref().map(|s| s.as_ref().and_then(map_stroke));
628	
629	    if mapped.iter().flatten().all(|v| Some(*v) == parent) {
630	        // All present values are equal to the parent value.
631	        return None;
632	    }
633	
634	    let Some(first) = mapped.iter().flatten().next() else {
635	        // All values are missing
636	        return None;
637	    };
638	
639	    // At least one value is different from the parent, fill up the remaining
640	    // sides with a replacement value.
641	    let replacement = default.unwrap_or(*first);
642	    let sides = mapped.unwrap_or(replacement);
643	
644	    // TODO(accessibility): handle `text(dir: rtl)`
645	    Some(sides.to_lrtb_krilla())
646	}
