5	pub struct Accumulator {
6	    pub nesting: ElementKind,
7	    buf: Vec<Node>,
8	    // An intermediate `Span` node to collect marked content sequences.
9	    // Grouping elements may not contain marked content sequences directly, so
10	    // they are wrapped into a `Span`.
11	    grouping_span: Option<Vec<Node>>,
12	}
13	
14	impl Accumulator {
15	    /// Create a new accumulator.
16	    fn new(nesting: ElementKind) -> Self {
17	        Self { nesting, buf: Vec::new(), grouping_span: None }
18	    }
19	
20	    /// Create a new accumulator.
21	    pub fn root() -> Self {
22	        Self::new(ElementKind::Grouping)
23	    }
24	
25	    /// Create a new nested accumulator. This will flush any intermediate
